'use strict';
(() => {
const D=globalThis.RA.D;
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:`${w}.q${i+1}`,senseId:`${w}.s${q.s}`,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('statue','Statue comes from Latin statua, “standing image,” from statuere, “set up”; it is a solid figure of a person or animal, usually made of stone or metal.',C('statue.s1','艺术','The bronze statue of the city’s founder stands beside the old courthouse.','这座青铜创城者雕像立在旧法院旁边。','a bronze/marble statue; statue of a person','名词，指通常用石头或金属制成的人物或动物立体像。','solid bronze figure depicts a person.','艺术'),M('The statue of the founder was a flat paper photograph with no solid shape.','The statue of the founder was a solid bronze figure.','statue指立体塑像，不是平面照片。','meaning'),[Q(1,'A statue is…','a solid figure of a person or animal','a written law passed by parliament','a small amount of tea','That matches the source definition.','meaning'),Q(1,'Where did the bronze statue stand?','Beside the old courthouse','Inside a steamboat engine','At the bottom of a spoon','The context identifies a solid public sculpture.','context'),Q(1,'Which phrase is natural?','a statue of the city’s founder','a statue the founder ofly','a founder statueing of city','Of introduces the person represented.','grammar'),Q(1,'Statue comes from Latin statua, related to a verb meaning…','set up','steal','steam','The Latin root statuere meant to set or establish.','word-formation')]);
P('statuette','Statuette came from French statuette, formed from statue with the diminutive ending -ette; it is a small-scale statue.',C('statuette.s1','艺术','The museum displayed a tiny bronze statuette beside the full-sized sculpture.','博物馆在真人大小的雕塑旁展出了一尊小巧的青铜小雕像。','a bronze/porcelain statuette; statuette of + person','名词，指按较小比例制作的雕像。','small figure contrasted with full-sized one.','艺术'),M('The museum called the life-sized bronze monument a statuette.','The museum called the small bronze figure a statuette.','statuette强调尺寸小，真人大小的纪念像不符合。','meaning'),[Q(1,'A statuette is…','a small-scale statue','a legal rule','a large steamship','That is the entry’s definition.','meaning'),Q(1,'How did the statuette compare with the sculpture?','It was tiny and displayed beside the full-sized work.','It was much larger than the museum.','It was a flat photograph.','The context highlights its small scale.','context'),Q(1,'Which phrase is natural?','a porcelain statuette','a statuetteful porcelain','a statue smallness of porcelain','Statuette is a count noun for a small sculpture.','grammar'),Q(1,'French -ette commonly indicates…','a small or diminutive form','a person who steals','a legal status','The suffix makes statuette a small statue.','word-formation')]);
P('stature','Stature comes from Latin statura, “height, size,” from statuere, “set up”; it means a person’s height or their reputation and importance.',[C('stature.s1','身体','Despite his short stature, the goalkeeper could reach the top corner of the goal.','尽管个子不高，这名守门员仍能扑到球门上角。','short/tall stature; a person’s stature','名词，不可数，指人的身高或体格大小。','height does not prevent the reach.','身体'),C('stature.s1','声望','Her work on public health gave her stature among researchers around the world.','她在公共卫生领域的研究使她在世界各地的研究人员中享有声望。','gain/achieve stature; a person of stature','名词，也指社会或专业领域中的声誉和重要性。','work earns professional respect.','声望')],M('His stature among scientists grew because of his research, although the phrase referred only to his physical height.','His stature among scientists grew because his work earned respect and importance.','stature可比喻声望，不限于身体高度。','distinction'),[Q(1,'Short stature refers to…','physical height','social influence only','the period someone stayed','Sense 1 is the bodily measurement.','meaning'),Q(1,'A researcher of great stature has…','high reputation and importance','exceptional physical height necessarily','a bronze statue','The figurative sense concerns standing among peers.','context'),Q(1,'Which phrase is natural?','a person of great stature','a great stature personly of','a staturely person great','Of great stature is a standard phrase.','grammar'),Q(1,'Stature comes from Latin statura, meaning…','height or size','steam or vapor','a short wooden board','The Latin source referred to height or size.','word-formation')]);
P('status','Status comes from Latin status, “condition, standing,” from stare, “stand”; it means a person’s social/legal position or a situation at a particular time.',[C('status.s1','社会','The application asks applicants to state their employment status.','申请表要求申请人说明自己的就业状况。','social/legal/immigration status; status as + noun','名词，指个人或群体的社会或法律地位、身份。','form asks about position.','社会'),C('status.s2','进展','The dashboard shows the current status of each repair request.','控制面板显示每项维修申请当前的处理情况。','current/status update; status of a project','名词，也指某个时间点的情况或进展状态。','dashboard gives present situation.','进展')],M('The dashboard gave the current status of the repair requests by refusing to show whether any had begun.','The dashboard showed the current status, including which repairs had begun.','status表示当前情况，完全不提供情况就没有显示状态。','meaning'),[Q(1,'Employment status concerns a person’s…','social or work position','height','current weather only','Sense 1 is position or standing.','meaning'),Q(2,'The status of a repair request shows…','its situation or progress at that time','the applicant’s family tree','the price of a statuette','Sense 2 refers to a current state.','context'),Q(1,'Which phrase is natural?','check the status of the order','check the status order ofly','status the orderly check at','Of introduces the item whose state is checked.','grammar'),Q(1,'Latin status originally referred to a condition or…','standing','stealing','a stagecoach','The Latin word is related to stare, “stand.”','word-formation')]);
P('statute','Statute comes from Latin statutum, “something established,” from statuere, “set up”; it is a law enacted by a legislature or a formal organizational rule.',[C('statute.s1','法律','The new statute requires landlords to install working smoke alarms.','新法令要求房东安装可正常工作的烟雾报警器。','pass/enact a statute; statute requires that','名词，指议会通过的成文法。','legislature-made rule imposes requirement.','法律'),C('statute.s2','组织','The club’s statute sets out how officers are elected and replaced.','俱乐部章程规定了负责人如何选举和更换。','a statute/bylaw of an organization','名词，也指组织制定的正式规章。','formal internal rule describes procedure.','组织')],M('The statute was a casual suggestion that members could ignore without any formal adoption.','The statute was a formally adopted law or organizational rule.','statute指正式制定的法律或规则，不是随意建议。','distinction'),[Q(1,'A statute passed by parliament is…','a formal written law','an informal suggestion','a social reputation','Sense 1 is legislation.','meaning'),Q(2,'A club statute may specify…','how officers are elected','how a bronze statue is carved','when spring begins','Sense 2 is an organization’s formal rule.','context'),Q(1,'Which phrase is natural?','enact a statute','enact a statute on casually','a statute enactment the','Enact is commonly used with laws.','collocation'),Q(1,'Statute comes from Latin statutum, meaning…','something established or set up','a small statue','a noisy argument','The Latin source referred to an established measure.','word-formation')]);
P('staunch','Staunch came through Anglo-French estancher, “stop, quench”; its modern adjective sense describes firm and loyal support that does not weaken.',C('staunch.s1','态度','A staunch supporter stayed with the team even after several disappointing seasons.','即使经历几个令人失望的赛季，这位坚定的支持者仍然支持球队。','a staunch ally/supporter; staunchly loyal','形容词，指坚定、忠诚、不易改变的支持。','loyalty continues through setbacks.','态度'),M('She was a staunch supporter who abandoned the cause as soon as it became difficult.','She was a staunch supporter who remained loyal through difficulties.','staunch强调支持坚定持久，不是遇难即弃。','meaning'),[Q(1,'A staunch supporter is…','firm and loyal in support','uncertain and ready to leave','a person who staffs a building','That is the adjective’s sense.','meaning'),Q(1,'What showed the supporter was staunch?','She stayed with the team through poor seasons.','She left after the first loss.','She changed her position every day.','The example demonstrates unwavering loyalty.','context'),Q(1,'Which phrase is natural?','a staunch ally','a staunchly ally','a staunchness ally','Staunch is an adjective before ally.','grammar'),Q(1,'The Anglo-French source of staunch meant…','stop or quench','stand on a stage','make a small statue','The historical verb referred to stopping or quenching.','word-formation')]);
P('stave','Stave is related to Old English stæf, “staff, stick”; a stave is a curved strip in a cask, while the verb can mean smash inward or ward something off.',[C('stave.s1','制桶','The cooper replaced a cracked stave in the wooden barrel.','制桶工更换了木桶上一块开裂的桶板。','a barrel/cask stave; wooden staves','名词，指组成木桶或木盆侧壁的弯曲木板。','one strip forms part of cask wall.','制桶'),C('stave.s1','防护','The thick door staved off the wind during the storm.','暴风雨期间，厚重的门挡住了寒风。','stave off danger/hunger; stave something in','动词短语stave off表示挡住、延缓；stave in表示向内砸破。','door keeps wind away.','防护')],M('The door staved off the wind by letting the storm blow directly into the room.','The door staved off the wind by blocking it from entering the room.','stave off表示阻挡或延缓，不是让其进入。','meaning'),[Q(1,'A stave in a barrel is…','a curved strip forming part of its wall','a metal spring','a legal act','Sense 1 names a barrel part.','meaning'),Q(1,'The door staved off the wind means it…','kept the wind away','let the wind enter freely','was made into a small statue','Stave off means ward off or prevent.','context'),Q(1,'Which phrase is natural?','stave off hunger','stave hunger away offly','stave to hunger at','Off forms the phrasal verb meaning ward off.','grammar'),Q(1,'Stave is related to Old English stæf, meaning…','staff or stick','law or statute','steam','The barrel strip shares a historical word family with stick/staff.','word-formation')]);
P('stay','Stay comes through Old French estayer/ester, ultimately Latin stare, “stand”; it means remain or live somewhere as a visitor, continue in a state, or a period spent somewhere.',[C('stay.s1','旅行','We stayed at a small hotel near the station for two nights.','我们在车站附近的一家小旅馆住了两晚。','stay at/in a place; stay with someone','动词，指留在某地或作为访客暂住。','visitors remain at hotel.','旅行'),C('stay.s2','状态','The patient stayed calm while the nurse changed the dressing.','护士更换敷料时，病人一直保持镇静。','stay calm/open/awake; stay in a state','动词，指继续保持某种状态。','state continues during procedure.','状态'),C('stay.s3','旅行','Their stay in the mountain village lasted four days.','他们在山村逗留了四天。','a short/overnight stay; enjoy one’s stay','名词，指在某地停留或住宿的一段时间。','period is four days.','旅行')],M('We stayed at the hotel for two nights by checking out after only ten minutes.','We stayed at the hotel for two nights before checking out.','住两晚与十分钟后退房不一致。','meaning'),[Q(1,'They stayed at a hotel means they…','remained there as visitors','continued to be calm','spent no time there','Sense 1 is lodging or remaining in a place.','meaning'),Q(2,'The patient stayed calm means the patient…','continued to be calm','left the hospital immediately','slept for four days','Sense 2 means remain in a state.','context'),Q(3,'A four-day stay is…','a period spent in a place','a law passed by parliament','a wooden barrel strip','Sense 3 is the noun for a visit period.','meaning'),Q(1,'Which phrase is natural?','stay with a friend','stay to a friend','stay at friendly','With can introduce the person one visits.','grammar')]);
P('steadfast','Steadfast combines stead, “place or position,” with fast, “firmly fixed”; it describes someone or something resolutely loyal or unchanging.',C('steadfast.s1','品格','Her steadfast commitment to the shelter continued through years of funding cuts.','多年经费削减期间，她对避难所的坚定承诺始终没有动摇。','steadfast support/loyalty; remain steadfast','形容词，指忠诚坚定、不会轻易改变。','commitment persists despite pressure.','品格'),M('He was steadfast in his promise, changing his position every time a new opinion appeared.','He was steadfast in his promise and did not change his position.','steadfast表示坚定不变，与不断改主意相反。','meaning'),[Q(1,'A steadfast commitment is…','firm and unlikely to weaken','temporary and easily abandoned','a period of lodging','That is the adjective’s meaning.','meaning'),Q(1,'Why was her commitment called steadfast?','It continued despite funding cuts.','She ended it at the first difficulty.','She forgot the shelter existed.','The example shows determination that does not weaken.','context'),Q(1,'Which phrase is natural?','remain steadfast in one’s support','steadfastly support as adjective','a steadfastness supporterly','Steadfast is an adjective used after remain.','grammar'),Q(1,'Steadfast combines stead with…','fast, meaning firmly fixed','spouse, meaning married partner','stature, meaning height','Fast here means firmly fixed, not speed.','word-formation')]);
P('steadfastly','Steadfastly is formed from steadfast + -ly; it means with determination and loyalty that do not weaken or change.',C('steadfastly.s1','品格','The volunteers steadfastly supported the families until permanent housing was available.','直到家庭获得永久住房，志愿者们始终坚定地支持着他们。','steadfastly support/defend; remain steadfastly committed','副词，表示坚定忠诚、不动摇地。','support continues to a clear endpoint.','品格'),M('The volunteers steadfastly supported the families only until the first inconvenience appeared.','The volunteers steadfastly supported the families through the difficulties.','坚定支持不会遇到第一点不便就立即结束。','meaning'),[Q(1,'To support a group steadfastly is to support it…','with loyalty that does not weaken','only while it is convenient','without knowing the group','Steadfastly describes unwavering support.','meaning'),Q(1,'How long did volunteers help?','Until permanent housing was available','Only until the first delay','For no time at all','The context shows lasting support.','context'),Q(1,'Which sentence uses steadfastly correctly?','She steadfastly defended the decision.','She was steadfastly defender of decision.','She steadfast defended the decision.','Steadfastly is the adverb modifying defended.','grammar'),Q(1,'Steadfastly is made by adding -ly to…','steadfast','steady','stature','The adverb derives from the adjective steadfast.','word-formation')]);
P('steadily','Steadily is formed from steady + -ly; it means at an even rate or in a gradual, continuous way.',C('steadily.s1','变化','The river level rose steadily after days of rain, without sudden jumps.','连日降雨后，河水水位持续平稳上升，没有突然暴涨。','rise/grow/increase steadily; work steadily','副词，表示以稳定速度持续进行或逐渐发展。','change is gradual and even.','变化'),M('The temperature rose steadily, jumping wildly from freezing to extreme heat every minute.','The temperature rose steadily at a gradual, even rate.','剧烈而频繁的跳变不属于稳定、匀速的变化。','meaning'),[Q(1,'A steadily rising river level…','increases gradually and continuously','jumps unpredictably every second','falls and rises without any pattern','Steadily means at an even rate.','meaning'),Q(1,'What happened after several rainy days?','The river rose without sudden jumps.','It remained completely dry.','It became a stadium.','The context illustrates gradual continuous change.','context'),Q(1,'Which phrase is natural?','work steadily toward a goal','steadily workness towardly a goal','work a steadily toward the goal','The adverb modifies the action work.','grammar'),Q(1,'Steadily is formed from steady plus…','-ly','-ness','-er','The suffix forms the adverb.','word-formation')]);
P('steady','Steady is from Old French estedier, related to a place or position; it means firm and not shaking, constant in rate, reliable in character, or make/become stable.',[C('steady.s1','状态','Keep the ladder steady while I climb to the roof.','我爬上屋顶时，请把梯子扶稳。','hold/keep something steady; a steady pace','形容词，指牢固不摇晃，或以均匀速度持续。','person prevents movement.','状态'),C('steady.s2','品格','We need a steady colleague who can be trusted with the evening shift.','我们需要一位沉稳可靠、可以托付晚班的同事。','a steady person/worker; steady support','形容词，也指理智可靠、不轻易慌乱或改变。','colleague is dependable.','品格'),C('steady.s3','动作','She steadied the tray with both hands before carrying the glasses.','她用双手把托盘扶稳后，才端着玻璃杯往前走。','steady something; steady oneself','动词，指使某物或自己保持稳定。','hands prevent tray from tipping.','动作')],M('She kept the ladder steady by shaking it back and forth while he climbed.','She kept the ladder steady by holding it firmly and preventing movement.','steady在此表示稳定不摇晃。','meaning'),[Q(1,'A steady ladder is…','firm and not shaking','moving unpredictably','a small sculpture','Sense 1 is physical stability.','meaning'),Q(2,'A steady colleague is…','reliable and calm','likely to panic or disappear','a person who steals items','Sense 2 describes dependable character.','context'),Q(3,'She steadied the tray means she…','made it stable','pushed it off the table','filled it with steam','Sense 3 is the verb making something stable.','meaning'),Q(1,'Which phrase is natural?','a steady pace','a steadily pace','a pace steadyingly','Steady is an adjective before pace.','grammar')]);
P('steak','Steak came into English from Old Norse steik, “roast meat”; it is a thick, flat piece of meat or fish.',C('steak.s1','饮食','The chef grilled a salmon steak and served it with lemon.','厨师烤了一块三文鱼排，配柠檬一起上桌。','beef/fish steak; a steak of salmon','名词，指切成厚片的肉或鱼。','thick flat portion is grilled.','饮食'),M('The menu called a thin spoonful of soup a steak.','The menu called the thick grilled piece of salmon a steak.','steak指厚切肉或鱼，不是少量汤。','distinction'),[Q(1,'A salmon steak is…','a thick flat piece of fish','a whole live salmon','a spoonful of soup','That is the broader dictionary sense.','meaning'),Q(1,'How was the salmon served?','Grilled with lemon','Wound onto a spool','Used as a wooden stave','The context uses steak for a cut of fish.','context'),Q(1,'Which phrase is natural?','a beef steak','a steakful beef','steak of beefly a','Beef modifies the type of steak.','grammar'),Q(1,'Steak came from Old Norse steik, meaning…','roast meat','firm position','written law','The historical word referred to roasted meat.','word-formation')]);
P('steal','Steal comes from Old English stelan, “take secretly”; it means take property without permission or intent to return it, or obtain something/move secretly.',[C('steal.s1','法律','Someone stole the bicycle from the locked courtyard overnight.','有人夜里从上锁的院子里偷走了自行车。','steal something from someone; steal a car','及物动词，指未经允许且无意归还地拿走他人财物。','property is taken without consent.','法律'),C('steal.s2','隐蔽','The cat stole into the kitchen while everyone was watching television.','大家看电视时，猫悄悄溜进了厨房。','steal into/out of; steal a glance','动词，也指偷偷移动、悄悄获得或偷看。','movement is quiet and secret.','隐蔽')],M('He stole the bicycle but planned to return it to its owner with permission the next morning.','He stole the bicycle without permission and did not intend to return it.','steal的核心义包含未经允许拿走且无意归还。','meaning'),[Q(1,'Someone stole the bicycle means the person…','took it without permission and did not intend to return it','borrowed it with the owner’s consent','repaired it for the owner','Sense 1 is theft.','meaning'),Q(2,'The cat stole into the kitchen means it…','moved there quietly and secretly','announced its arrival loudly','stole a bicycle','Sense 2 is secret movement.','context'),Q(1,'Which phrase is correct?','steal a wallet from a pocket','steal a wallet to a pocket fromly','steal from a wallet to pocket','From introduces the owner or place something is taken from.','grammar'),Q(1,'Steal comes from Old English…','stelan','stabilitas','stare','The old verb meant to take secretly.','word-formation')]);
P('stealer','Stealer is formed from steal + -er; it means a person who takes something from a shop or another person without permission.',C('stealer.s1','法律','The shop identified the stealer from security footage and reported the missing watch.','商店从监控录像中认出了偷东西的人，并报告手表失窃。','a shop stealer; identify/catch a stealer','名词，指未经允许从商店或他人处拿走物品的人。','person takes watch without permission.','法律'),M('The stealer paid for the watch and received the owner’s permission to take it.','The stealer took the watch without permission.','经付款并获准拿走不是偷窃。','meaning'),[Q(1,'A stealer is…','a person who takes something without permission','a person who lends property willingly','a police officer in every case','That is the source definition.','meaning'),Q(1,'How did the shop identify the stealer?','From security footage','From a sonnet','By using a springboard','The context explains how the person was identified.','context'),Q(1,'Which phrase is natural?','catch the stealer','catch the stealful','catch the stealingly','Stealer is a count noun for the person.','grammar'),Q(1,'Stealer is formed from steal plus…','-er','-ity','-less','The suffix forms an agent noun.','word-formation')]);
P('stealing','Stealing is formed from steal + -ing; it names the act of taking something that belongs to another person without permission.',C('stealing.s1','法律','The store installed cameras to discourage stealing of small electronics.','商店安装摄像头，以防止小型电子产品被盗。','stealing from a shop; prevent/discourage stealing','名词，指未经允许拿走他人财物的行为。','cameras deter theft.','法律'),M('The store called it stealing even though every customer had paid for the electronics and taken them with permission.','The store called it stealing because the electronics were taken without payment or permission.','已付款并获准拿走不属于偷窃。','distinction'),[Q(1,'Stealing is…','the act of taking property without permission','the act of lending something','a type of sports uniform','That is the noun’s meaning.','meaning'),Q(1,'Why install cameras?','To discourage theft of small electronics','To help people steal unnoticed','To make a stagecraft display','Cameras are used to deter stealing.','context'),Q(1,'Which phrase is natural?','stealing from a shop','stealing a shop fromly','stealings from a shop','Stealing names the activity and is normally uncountable here.','countability'),Q(1,'Stealing is the -ing form of…','steal','steady','steam','It is built from the verb steal.','word-formation')]);
P('stealthy','Stealthy is formed from stealth + -y; stealth came through Old French from a Germanic word for theft, and the adjective means quiet and secret to avoid notice.',C('stealthy.s1','行动','The fox made a stealthy approach to the henhouse under cover of darkness.','狐狸趁着夜色悄悄靠近鸡舍。','a stealthy movement/approach; move stealthily','形容词，指行动安静隐蔽、不想被注意到。','animal moves quietly in darkness.','行动'),M('The thief made a stealthy entrance by shouting loudly and switching on every light.','The thief made a stealthy entrance by moving quietly in the dark.','大声喊叫并开灯会引人注意，不是隐蔽行动。','meaning'),[Q(1,'A stealthy approach is…','quiet and secret to avoid notice','loud and deliberately public','a stable legal status','That is the adjective’s sense.','meaning'),Q(1,'How did the fox approach the henhouse?','Quietly under cover of darkness','By making a loud announcement','On a stagecoach','The context shows concealment.','context'),Q(1,'Which phrase is natural?','a stealthy movement','a stealthy moveful','stealthily movement','Stealthy is an adjective modifying movement.','grammar'),Q(1,'Stealthy is formed from stealth plus…','-y','-er','-ness','The suffix forms an adjective.','word-formation')]);
P('steam','Steam is from Old English stēam, “vapor, exhalation”; it is hot gas from boiling water, and the verb means cook with it, give it off, or move by steam power.',[C('steam.s1','科学','Steam rose from the kettle after the water reached boiling point.','水烧开后，蒸汽从水壶里升起。','cloud of steam; steam from boiling water','名词，指水沸腾时产生的热气体。','heated water becomes vapor.','科学'),C('steam.s2','烹饪','Steam the broccoli for five minutes so that it remains bright and tender.','把西兰花蒸五分钟，让它保持鲜绿和鲜嫩。','steam vegetables; steam something for + time','动词，指用蒸汽烹饪、产生蒸汽或靠蒸汽行驶。','food cooks above boiling water.','烹饪')],M('Steam rose from the kettle while the water remained frozen solid and unheated.','Steam rose from the kettle after the water boiled.','沸水产生蒸汽，冰冻未加热的水不会产生蒸汽。','meaning'),[Q(1,'Steam from a boiling kettle is…','hot gas produced when water boils','a cold solid','a small statue','That is the noun sense.','meaning'),Q(2,'To steam broccoli is to…','cook it using steam','fry it in dry oil','freeze it solid','Sense 2 is the cooking verb.','context'),Q(1,'Which phrase is natural?','steam the vegetables for five minutes','steam to the vegetables fively','steamed vegetables by a steamly','The verb can take the food as a direct object.','grammar'),Q(1,'Steam descends from Old English stēam, meaning…','vapor or exhalation','firm loyalty','a small troop','The old word already referred to vapor.','word-formation')]);
P('steamboat','Steamboat combines steam + boat; it is a vessel propelled by steam power, often a paddle boat used on rivers.',C('steamboat.s1','交通','The steamboat carried passengers up the river before the railway bridge was built.','铁路桥建成前，蒸汽船载着乘客沿河而上。','river steamboat; travel by steamboat','名词，指用蒸汽动力推进的船，常见于河上。','steam power moves vessel upstream.','交通'),M('The steamboat crossed the river under sail alone and had no steam engine.','The steamboat crossed the river using a steam engine.','steamboat以蒸汽为动力，不是纯帆船。','meaning'),[Q(1,'A steamboat is…','a vessel propelled by steam','a small statue made of bronze','a law passed by parliament','That is the source definition.','meaning'),Q(1,'What did the steamboat do on the river?','Carried passengers upstream','Stored horses in a stable','Made a short sprint','The example shows it as river transport.','context'),Q(1,'Which phrase is natural?','travel by steamboat','travel at steamboatly','steamboat travel the by','By introduces the means of travel.','grammar'),Q(1,'Steamboat is a compound of steam and…','boat','board','spouse','The compound names a boat powered by steam.','word-formation')]);
P('steamer','Steamer combines steam + -er; it means a steam-powered ship or a pot/device used to cook food with steam.',[C('steamer.s1','交通','A small steamer brought mail and supplies to the island each week.','一艘小型汽船每周给岛上运送邮件和补给。','a passenger steamer; travel aboard a steamer','名词，指由蒸汽动力驱动的船。','ship carries goods on schedule.','交通'),C('steamer.s2','厨房','Place the dumplings in the steamer above a pot of boiling water.','把饺子放进蒸笼，再把蒸笼架在一锅沸水上。','a vegetable/rice steamer; put food in a steamer','名词，也指利用蒸汽烹饪食物的锅或器具。','steam cooks the dumplings.','厨房')],M('She put the dumplings in the steamer, then cooked them by submerging them in cold oil.','She put the dumplings in the steamer above boiling water.','steamer用蒸汽烹饪，不是冷油浸炸。','distinction'),[Q(1,'A passenger steamer is…','a ship driven by steam power','a small cooking spoon','a stone statue','Sense 1 is the vessel.','meaning'),Q(2,'A kitchen steamer cooks dumplings with…','steam above boiling water','cold oil','a spotlight','Sense 2 is a cooking device.','context'),Q(1,'Which phrase is natural?','put rice in the steamer','put rice in the steamerly','steamer rice to in put','In introduces the cooking container.','grammar'),Q(1,'Steamer is formed from steam plus…','-er','-ity','-less','The suffix creates a noun for a device or vessel.','word-formation')]);
P('steamship','Steamship combines steam + ship; it is a ship powered by a steam engine rather than by sails.',C('steamship.s1','航运','The steamship crossed the Atlantic even when the wind was too weak to fill its sails.','即使风力弱到无法鼓起船帆，这艘蒸汽轮船仍横渡了大西洋。','ocean-going steamship; travel by steamship','名词，指以蒸汽为动力、区别于帆船的船只。','engine propels ship despite weak wind.','航运'),M('The steamship crossed the ocean under sail alone, with its engine permanently removed.','The steamship crossed the ocean using its steam-powered engine.','steamship以蒸汽发动机为动力，不是纯帆船。','meaning'),[Q(1,'A steamship is…','a ship powered by steam','a ship moved only by sails','a steam-cooking pot','That is the source definition.','meaning'),Q(1,'Why could it travel despite weak wind?','Its steam engine propelled it.','Its sails caught a stronger wind.','It was a steppe vehicle.','The example contrasts engine power with sailing.','context'),Q(1,'Which phrase is natural?','a steamship crossed the ocean','a steamshiply crossed ocean','crossed a ship of steamshiping','The compound is a count noun naming a vessel.','grammar'),Q(1,'Steamship combines steam and…','ship','sail','stair','The compound identifies the ship’s propulsion.','word-formation')]);
P('stearin','Stearin comes from Greek stear, “fat”; it is a solid fat, chiefly glyceryl tristearate, used to harden candles and in soap-making.',C('stearin.s1','化学','The candle maker added stearin to make the wax mixture harder.','蜡烛制造者加入硬脂精，使蜡料变得更硬。','stearin in candles/soap; solid stearin','名词，不可数，指主要用于蜡烛和制皂的固态脂肪。','additive stiffens candle wax.','化学'),M('The candle maker added stearin to make the wax softer and more liquid.','The candle maker added stearin to make the wax harder.','stearin常用于使蜡烛材料变硬，而非变软。','meaning'),[Q(1,'Stearin is…','a solid fat used in candles and soap','a gas from boiling water','a metal alloy','That is the chemical sense.','meaning'),Q(1,'Why add stearin to candle wax?','To stiffen the mixture','To make it more liquid','To steer the candle','The example gives its hardening function.','context'),Q(1,'Which phrase is natural?','add stearin to the candle mixture','add a stearin to mixture candle','stearins in candlely','Stearin is normally an uncountable substance noun.','countability'),Q(1,'Stearin comes from Greek stear, meaning…','fat','star','step','The Greek source referred to fat.','word-formation')]);
P('steel','Steel comes from Old English stȳle, a Germanic word; it is a hard alloy of iron and carbon, and the verb means prepare oneself to do something difficult.',[C('steel.s1','材料','The bridge cables are made of steel because the alloy can bear heavy loads.','桥梁缆索由钢制成，因为这种合金能够承受重载。','steel beams/tools; made of steel','名词，不可数，指铁与碳混合制成的坚硬金属。','alloy supports heavy weight.','材料'),C('steel.s2','心理','She steeled herself for the difficult conversation with her manager.','她让自己做好心理准备，去和经理进行那场艰难谈话。','steel oneself for something; steel oneself to do','动词，指使自己坚强起来以面对困难。','prepares mentally.','心理')],M('She steeled herself for the difficult call by refusing to prepare and panicking before dialing.','She steeled herself for the call by gathering her courage before dialing.','steel oneself是鼓起勇气、做好心理准备。','meaning'),[Q(1,'Steel in a bridge cable is…','a strong hard alloy of iron and carbon','pure liquid iron','a material made from steam','Sense 1 is the metal.','meaning'),Q(2,'She steeled herself for a conversation means she…','prepared herself mentally for something difficult','made herself physically into metal','avoided the conversation forever','Sense 2 is the verb meaning strengthen one’s resolve.','context'),Q(1,'Which phrase is natural?','steel yourself for the interview','steel yourself at interviewly','steel to yourself the interview for','For introduces the difficult event one prepares for.','grammar'),Q(1,'Steel is an alloy chiefly based on iron and…','carbon','stearin','water vapor','Carbon is mixed with iron to make steel.','word-formation')]);
P('steep','Steep comes from Old English stēap, “high, lofty”; it describes a sharp incline or a sudden large change, and may mean more expensive than reasonable.',[C('steep.s1','地形','The path becomes steep near the summit, so hikers use both hands for support.','小路接近山顶时变得很陡，徒步者得用双手支撑。','a steep hill/slope; steep road','形容词，指斜度很大、迅速升高或下降。','sharp incline requires support.','地形'),C('steep.s2','价格','The hotel charged a steep fee for parking during the festival.','节日期间，这家酒店收取的停车费高得离谱。','a steep price/fee/increase; pay a steep price','形容词，也指金额突然很大或高得不合理。','fee is unusually high.','价格')],M('The trail was steep, rising only one metre over a distance of several kilometres.','The trail was steep, climbing sharply over a short distance.','缓慢升高的路段不算陡峭。','meaning'),[Q(1,'A steep path near a summit…','rises at a sharp angle','is completely flat','is a metal alloy','Sense 1 describes the slope.','meaning'),Q(2,'A steep parking fee is…','unreasonably high','very small and affordable','a short journey','Sense 2 concerns cost.','context'),Q(1,'Which phrase is natural?','a steep increase in rent','a steeply increase in rent','a steepness rent increase','Steep is an adjective modifying increase.','grammar'),Q(1,'The Old English source of steep meant…','high or lofty','cold or frozen','paid employment','The adjective developed from the sense “high.”','word-formation')]);
P('steeple','Steeple comes from Old English stīepel, a pointed tower; it is a tall structure on a church roof, often containing a clock.',C('steeple.s1','建筑','The church steeple was visible from the village road above the treetops.','从村道上望去，教堂尖塔高出树梢，清晰可见。','church steeple; climb the steeple','名词，指教堂屋顶上高而尖的塔状结构，常装有钟。','pointed tower rises above roof.','建筑'),M('The church steeple was a short underground room hidden beneath the floor.','The church steeple was a tall pointed structure rising above the roof.','steeple指高耸的尖塔，不是地下室。','meaning'),[Q(1,'A church steeple is…','a tall pointed structure on the roof','a curved strip in a barrel','a legal rule','That is the architectural sense.','meaning'),Q(1,'Why could villagers see the steeple from the road?','It rose above the treetops.','It was hidden underground.','It was a small spoon.','Its height makes it visible.','context'),Q(1,'Which phrase is natural?','the church steeple','the church steeplingly','steeple of church roofed','Steeple names the pointed church structure.','grammar'),Q(1,'Steeple descends from Old English…','stīepel','stear','squall','The Old English noun referred to a tower.','word-formation')]);
P('steer','Steer is from Old English stīeran, “guide, direct”; it means control a vehicle’s direction or guide someone toward a course of action.',[C('steer.s1','交通','The ferry captain steered the vessel around the rocks near the harbor entrance.','渡船船长操纵船只绕过港口入口附近的岩石。','steer a car/ship; steer around an obstacle','及物动词，指控制车辆、船只的行进方向。','captain changes vessel’s direction.','交通'),C('steer.s2','引导','The mentor steered the student toward a research topic that matched her interests.','导师把学生引向一个符合她兴趣的研究主题。','steer someone toward/away from; steer a discussion','动词也指引导某人朝某个选择或方向发展。','mentor guides choice.','引导')],M('The captain steered the ferry into the rocks by guiding it safely around them.','The captain steered the ferry around the rocks and away from danger.','绕开岩石与驶入岩石相反。','meaning'),[Q(1,'The captain steered the ferry means he…','controlled its direction','built the ferry from steel','stayed at the harbor','Sense 1 is navigation.','meaning'),Q(2,'A mentor steered a student toward a topic by…','guiding her choice','forcing her to leave school','stiffening the research paper','Sense 2 is figurative guidance.','context'),Q(1,'Which construction is natural?','steer the boat around the rocks','steer around the boat rocks at','steer to boat rocks','Around marks the route avoiding an obstacle.','grammar'),Q(1,'Steer comes from Old English stīeran, meaning…','guide or direct','stand still','make a statute','The verb’s historical meaning was to guide.','word-formation')]);
P('steering','Steering is formed from steer + -ing; it names the act or equipment used to control a vehicle’s direction.',C('steering.s1','交通','The car’s steering felt loose, so the mechanic checked the front wheels.','汽车转向装置感觉松动，因此技工检查了前轮。','steering wheel/system; power steering','名词，指车辆转向的动作或控制方向的装置。','mechanic checks directional control.','交通'),M('The car’s steering was loose, so the wheels turned precisely and safely without repair.','The car’s steering was loose, so the mechanic repaired its directional control.','转向松动表示操纵有问题，不是精准安全。','meaning'),[Q(1,'Car steering is…','the equipment or act controlling its direction','the engine’s fuel','the time spent in a hotel','That is the source sense.','meaning'),Q(1,'Why did the mechanic check the front wheels?','The steering felt loose.','The car had a steeple.','A steak was cooking.','The steering problem concerns directional control.','context'),Q(1,'Which phrase is natural?','power steering','power steeringly','steering powerfully as verb','Steering is a noun in this collocation.','grammar'),Q(1,'Steering is based on the verb…','steer','steel','stay','The noun names the act or mechanism of steering.','word-formation')]);
P('stele','Stele comes from Greek stēlē, “pillar, slab”; it is an upright stone carved or inscribed as a monument.',C('stele.s1','考古','Archaeologists found a carved stele bearing the names of the rulers.','考古学家发现了一块刻有统治者姓名的石碑。','an inscribed stele; stone stele','名词，指竖立起来、刻有文字或图案的纪念石柱或石板。','upright stone carries inscription.','考古'),M('The archaeologists called a loose paper leaflet on the ground a stele.','The archaeologists called the carved upright stone monument a stele.','stele是竖立的石制纪念物，不是纸张。','meaning'),[Q(1,'A stele is…','an upright carved or inscribed stone monument','a tall church roof','a sports team','That is the archaeological meaning.','meaning'),Q(1,'What was carved on the stele?','The rulers’ names','A spoonful of sugar','A ship’s steering wheel','The context gives the inscription content.','context'),Q(1,'Which phrase is natural?','an inscribed stone stele','a steleful of stone','a stone inscribedly stele','Inscribed modifies the monument.','grammar'),Q(1,'Stele comes from Greek stēlē, meaning…','pillar or slab','steam or vapor','a state or status','The Greek word referred to a pillar or slab.','word-formation')]);
P('stellar','Stellar comes from Latin stellaris, from stella, “star”; it means relating to stars or, figuratively, outstanding in quality.',[C('stellar.s1','天文','The observatory recorded a stellar event as a bright star exploded in the distant galaxy.','一颗遥远星系中的亮星爆发时，天文台记录了这一恒星现象。','stellar light/object; stellar astronomy','形容词，指与恒星或星星有关的。','event occurs in a star.','天文'),C('stellar.s1','评价','The chef received stellar reviews for the tasting menu.','这位厨师的品尝菜单获得了极高评价。','stellar performance/review; do a stellar job','形容词也比喻表示极其出色的。','reviews praise quality.','评价')],M('The chef’s stellar reviews described the meal as poor, disappointing, and badly prepared.','The chef received stellar reviews praising the meal as outstanding.','stellar评价表示非常出色，不是糟糕。','distinction'),[Q(1,'A stellar event in astronomy is…','an event involving a star','a church tower','a legal statute','Sense 1 is star-related.','meaning'),Q(1,'Stellar reviews are…','outstandingly positive','strongly negative','about a person’s height','The figurative use means excellent.','context'),Q(1,'Which phrase is natural?','a stellar performance','a stellarize performance','a stellarly performance','Stellar is an adjective before performance.','grammar'),Q(1,'Stellar is related to Latin stella, meaning…','star','steam','steal','The Latin root means star.','word-formation')]);
P('stem','Stem comes from Old English stemn, “stalk”; it can name a plant’s main stalk or a word’s base, mean stop a flow, or describe something as originating from a source.',[C('stem.s1','植物','The flower’s stem bent under the weight of the wet petals.','花茎在湿花瓣的重量下弯了下来。','plant/flower stem; stem of a leaf','名词，指支撑叶子和花朵的植物主要长茎。','stalk supports petals.','植物'),C('stem.s2','语言','Add the plural ending to the stem of the noun.','把复数词尾加到这个名词的词干上。','word stem; stem + suffix','名词，指添加词尾前的词的主要部分。','ending attaches to base.','语言'),C('stem.s3','控制','New barriers helped stem the spread of the invasive plant.','新的屏障有助于遏制这种入侵植物的扩散。','stem a flow/tide/spread; stem the losses','动词，指阻止或减缓某种增长、扩散或流动。','barriers slow spread.','控制'),C('stem.s4','起源','Most of the confusion stemmed from one unclear sentence in the contract.','大部分混乱都源于合同里一句含糊不清的话。','stem from a cause/source','动词短语，指由某个原因或来源产生。','unclear sentence causes confusion.','起源')],M('The new barriers stemmed the invasive plant by helping it spread faster across the field.','The new barriers stemmed the invasive plant’s spread by slowing its growth.','stem作动词表示遏制，不是促进扩散。','meaning'),[Q(1,'A flower stem is…','the main stalk supporting leaves and flowers','the flower’s legal position','a small stone monument','Sense 1 is the plant part.','meaning'),Q(2,'A word stem is…','the base to which endings are added','a plant stalk in a pot','a short race','Sense 2 is the linguistic base.','context'),Q(3,'Stem the spread means…','stop or slow it','help it expand','describe its height','Sense 3 means restrain.','meaning'),Q(4,'Confusion stemmed from a sentence means it…','originated from that sentence','was prevented by the sentence','was turned into a plant','Sense 4 identifies a cause.','meaning')]);
P('stem from','Stem from combines stem in the sense “originate” with from; it means be the result of a particular cause or develop from a source.',C('stem from.s1','因果','The delay stemmed from a faulty signal that stopped the trains.','延误源于一个导致列车停运的故障信号。','problems stem from; stem from a cause/source','动词短语，表示某种结果由特定原因产生或发展而来。','faulty signal causes delay.','因果'),M('The delay stemmed from the faulty signal, but the signal had no connection to the trains stopping.','The delay stemmed from the faulty signal that stopped the trains.','stem from表示因果来源，此处故障信号确实造成了延误。','meaning'),[Q(1,'The delay stemmed from a faulty signal means it…','was caused by that signal','caused the signal to appear later','was unrelated to any cause','Stem from identifies an origin or cause.','meaning'),Q(1,'What caused the trains to stop?','A faulty signal','A steeple','A steak','The example states the signal was the source of the delay.','context'),Q(1,'Which construction is correct?','The error stemmed from a typo.','The error stemmed a typo from.','The error was stemmed to a typo.','From introduces the cause.','grammar'),Q(1,'In stem from, from introduces…','the source or cause','the result only','the person who steers','The phrase links a result to its origin.','meaning')]);
P('stench','Stench comes from Old English stenc, “smell, odor”; it means an extremely strong unpleasant smell that is often hard to escape.',C('stench.s1','感官','A stench of rotten eggs filled the basement after the pipe broke.','管道破裂后，一股臭鸡蛋般的恶臭充满了地下室。','a foul/strong stench; stench of + source','名词，指很强烈、令人不快且常难以避开的气味。','odor fills enclosed room.','感官'),M('The basement’s stench was a faint pleasant perfume that everyone wanted to smell.','The basement’s stench was a powerful foul odor from the broken pipe.','stench指强烈难闻的气味，不是淡淡香水味。','meaning'),[Q(1,'A stench is…','a very strong unpleasant smell','a faint pleasant fragrance','a metallic sound','That is the word’s meaning.','meaning'),Q(1,'What caused the stench in the basement?','A broken pipe and rotten-egg odor','A bowl of fresh soup','A new statute','The context names the source of the foul smell.','context'),Q(1,'Which phrase is natural?','a stench of rotten eggs','a stenchful eggs of','a stench from smellly eggs','Of introduces the smell’s source.','grammar'),Q(1,'Stench comes from Old English…','stenc','stēam','stīepel','The Old English word meant smell or odor.','word-formation')]);
P('stencil','Stencil is of uncertain deeper origin; it names a thin sheet with cut-out patterns through which paint or ink is applied.',C('stencil.s1','工艺','She held a stencil over the wall and painted the leaf pattern through its openings.','她把模板贴在墙上，透过镂空部分刷出了叶片图案。','a stencil for letters; paint through a stencil','名词，指带有镂空图样、用于转印油墨或颜料的薄片。','openings guide the paint.','工艺'),M('She used a stencil by painting solid areas that had no cut-out pattern or openings.','She used a stencil with cut-out openings to guide the painted pattern.','模板靠镂空部分限制颜料的位置。','meaning'),[Q(1,'A stencil is…','a thin sheet with a cut-out pattern','a thick metal alloy','a device for hearing heartbeats','That is the craft sense.','meaning'),Q(1,'How did she make the leaf pattern?','She painted through the stencil openings.','She carved the entire wall.','She used a steamboat.','The cutouts guide where paint reaches the surface.','context'),Q(1,'Which phrase is natural?','paint through a stencil','paint a stencil throughly of','stencil the paint byly','Through identifies the openings used to transfer the pattern.','grammar'),Q(1,'The deeper origin of stencil is…','uncertain','certainly from Latin stella','certainly from steamship','The word’s earlier derivation is not confidently established.','word-formation')]);
P('stenography','Stenography combines Greek stenos, “narrow,” with -graphy, “writing”; it is the skill of recording speech quickly with abbreviations or special signs.',C('stenography.s1','记录','The court reporter used stenography to record every witness’s words in real time.','法庭记录员用速记法实时记录每位证人的发言。','learn/practise stenography; stenography system','名词，不可数，指用简写或特殊符号快速记录口语的技能。','special shorthand captures speech quickly.','记录'),M('The reporter used stenography by writing every word out slowly in full while the speakers waited.','The reporter used stenography to capture the spoken words rapidly with shorthand signs.','stenography的目的正是快速记录口语。','meaning'),[Q(1,'Stenography is…','a skill for rapidly writing down speech using shorthand','a method of carving stone monuments','a sports rule','That is the source definition.','meaning'),Q(1,'Why did the court reporter use stenography?','To record testimony in real time','To make the witness speak more slowly','To steer a ship','Shorthand enables rapid recording.','context'),Q(1,'Which phrase is natural?','learn stenography','learn a stenographyly','stenography to learn at','Stenography is an uncountable skill or field.','grammar'),Q(1,'Greek stenos meant…','narrow','star','stable','It refers to the compact or shortened writing system.','word-formation')]);
P('step','Step comes from Old English steppan, “move the foot”; it names a foot movement, an action in a sequence, or a stair tread, and the verb means move or place the foot.',[C('step.s1','动作','Take one step back from the edge of the platform.','从站台边缘往后退一步。','take a step; step back/forward','名词，指抬起脚再放下的一次动作。','one foot movement creates distance.','动作'),C('step.s2','程序','The first step in the application is to upload proof of address.','申请流程的第一步是上传地址证明。','the first/next step; take steps to do','名词，指完成目标的一系列行动中的一个步骤。','action begins process.','程序'),C('step.s3','建筑','She sat on the lowest step of the library entrance to wait for her friend.','她坐在图书馆入口最低一级台阶上等朋友。','front/top step; climb the steps','名词，指上下楼梯或入口时供脚踩的平面。','tread supports her foot.','建筑'),C('step.s4','动作','Step carefully onto the wet stone so you do not slip.','小心踩上湿石头，免得滑倒。','step on/into/onto; step aside','动词，指抬脚移动或踩到某处。','foot is placed on stone.','动作')],M('Take one step back from the platform by moving closer to its edge.','Take one step back from the platform by increasing your distance from its edge.','step back表示往后退、远离边缘。','meaning'),[Q(1,'One step back is…','one movement of a foot away from the edge','one stage in an application','a flat stair surface','Sense 1 is a foot movement.','meaning'),Q(2,'The first step in an application is…','one action in a series','a physical stair','a metal strip in a barrel','Sense 2 is a procedural action.','context'),Q(3,'The lowest step at the entrance is…','a flat surface to put a foot on','a place to stay overnight','a steel alloy','Sense 3 is a stair tread.','meaning'),Q(4,'Step onto the stone means…','move your foot onto it','stand still without moving','carve a statue','Sense 4 is the verb.','meaning')]);
P('step down','Step down combines step + down; it means leave an important position voluntarily, usually before being forced to leave.',C('step down.s1','职场','The chair agreed to step down after the board selected a successor.','董事会选定继任者后，主席同意辞职。','step down as/from; call on someone to step down','动词短语，指辞去重要职务或职位。','chair leaves role voluntarily.','职场'),M('The chair stepped down but remained in the same position with unchanged authority.','The chair stepped down and left the leadership position.','step down指离开重要职位，不是继续留任。','meaning'),[Q(1,'A chair who steps down…','leaves the leadership position','climbs to a higher position','takes the first procedural step','That is the phrasal verb’s sense.','meaning'),Q(1,'Why did the chair step down?','The board had selected a successor.','The chair was appointed to the same post again.','The stadium opened.','The context gives the reason for leaving office.','context'),Q(1,'Which phrase is natural?','step down as chair','step down the chair at','step down for chairing','As introduces the role being left.','grammar'),Q(1,'Step down is a phrasal verb meaning…','resign from an important position','move forward to volunteer','intervene in a quarrel','Down marks leaving a position.','meaning')]);
P('step forward','Step forward combines step + forward; it means offer oneself to help or say one is willing to take responsibility.',C('step forward.s1','帮助','Two neighbors stepped forward to organize meals for the family after the fire.','火灾后，两位邻居主动站出来为这家人安排饭菜。','step forward to help; step forward as a volunteer','动词短语，指主动提出帮忙或承担责任。','neighbors volunteer without being asked.','帮助'),M('No one stepped forward to help, although three people volunteered immediately.','Three people stepped forward to help without being asked.','主动报名就是step forward，不能同时说没人站出来。','meaning'),[Q(1,'Neighbors who stepped forward…','offered help or responsibility','resigned from their positions','stayed invisible and silent','That is the phrase’s sense.','meaning'),Q(1,'What did the neighbors offer to do?','Organize meals for the family','Replace a church steeple','Steal a bicycle','The example shows voluntary assistance.','context'),Q(1,'Which construction is natural?','step forward to help','step forward for helping toly','step to forward help','To introduces the offered action.','grammar'),Q(1,'Step forward in this expression signals…','volunteering or taking responsibility','moving backward from danger','being forced to resign','The phrase means present oneself for a task.','meaning')]);
P('step in','Step in combines step + in; it means become involved in a situation, often to help or stop an argument.',C('step in.s1','调解','A teacher stepped in when the argument between the students became heated.','学生间的争吵变得激烈时，老师介入了。','step in to help/stop; step in when','动词短语，指介入某事以帮助或制止问题。','teacher intervenes to prevent escalation.','调解'),M('The teacher stepped in by watching the argument from a distance and refusing to become involved.','The teacher stepped in by intervening to stop the argument.','step in表示介入，不是旁观不管。','meaning'),[Q(1,'A teacher who steps in…','becomes involved to help or stop trouble','leaves the room and refuses to help','steps down from a job','That is the phrasal verb’s meaning.','meaning'),Q(1,'Why did the teacher step in?','The argument became heated.','The students were quietly reading.','A ship needed steam.','The context provides the reason for intervention.','context'),Q(1,'Which phrase is natural?','step in to prevent a fight','step in preventingly a fight to','step into a prevent fight at','To introduces the purpose of intervening.','grammar'),Q(1,'Step in is closest in meaning to…','intervene','resign','squander','It means enter a situation and become involved.','meaning')]);
P('steppe','Steppe came into English through Russian step’, a word for an extensive open plain; it is a vast treeless grassland in a dry climate.',C('steppe.s1','地理','Wild horses crossed the dry steppe, where trees were scarce and grass stretched to the horizon.','野马穿过干燥的大草原，那里树木稀少，草地一直延伸到地平线。','the Eurasian steppe; steppe grassland','名词，指干燥气候下辽阔、无树的草原。','open treeless plain.','地理'),M('The steppe was a dense rainforest covered with tall trees and constant heavy rain.','The steppe was a vast, dry, treeless grassland.','steppe是干燥无树草原，不是雨林。','meaning'),[Q(1,'A steppe is…','a vast treeless plain with dry grassland','a wet tropical forest','a small church tower','That is the geographic sense.','meaning'),Q(1,'What crossed the steppe?','Wild horses','A steamboat in a harbor','A theater audience','The context depicts open grassland.','context'),Q(1,'Which phrase is natural?','grass grows across the steppe','grass grows steppewardly acrossly','a steppe of grasses are','Across describes the extent of the plain.','grammar'),Q(1,'Steppe entered English through Russian…','step’','stēam','statuette','The geographical term is borrowed from Russian.','word-formation')]);
P('stepper','Stepper is formed from step + -er; it can name something that moves in steps, such as a high-stepping horse, a stepper motor, or a chip-making machine.',C('stepper.s1','机械','The stepper motor moved the camera platform a precise fraction of a turn at a time.','步进电机每次让摄像平台精确转动一小段角度。','stepper motor; high stepper','名词，指按固定步幅移动的机械装置，也可指步幅高的马等。','motor advances in discrete steps.','机械'),M('The stepper motor rotated continuously at random speeds without moving in measured increments.','The stepper motor advanced the platform in precise increments.','步进电机按一个个固定步距移动。','meaning'),[Q(1,'A stepper motor moves…','in precise separate increments','only in one continuous unmeasured slide','by using steam','That describes a stepper mechanism.','meaning'),Q(1,'What did the stepper motor move?','The camera platform','A steeple','A steak','The context illustrates its controlled motion.','context'),Q(1,'Which phrase is standard?','a stepper motor','a stepper motorly','a motor steppering','Stepper modifies motor as a compound noun.','grammar'),Q(1,'Stepper is formed from step plus…','-er','-ity','-less','The suffix can name a thing that moves in steps.','word-formation')]);
P('steps','Steps is the regular plural of step; it names a set of stairs or a series of actions taken to achieve a goal.',[C('steps.s1','建筑','The stone steps leading to the library were slippery after the rain.','雨后通往图书馆的石阶很滑。','climb/go down the steps; front steps','复数名词，指连接不同高度的一组台阶。','several treads form staircase.','建筑'),C('steps.s2','计划','The first steps toward reopening the clinic are to hire nurses and test the equipment.','重新开放诊所的第一批措施是招聘护士并检测设备。','take steps to do; follow the steps','复数名词，也指按顺序完成目标的一系列行动。','actions are part of a process.','计划')],M('The stone steps were a single flat surface with no levels to climb.','The stone steps formed several levels leading to the library.','steps复数义项是楼梯或台阶组，不是单一平面。','meaning'),[Q(1,'Stone steps are…','a set of flat surfaces for moving between levels','a single vertical wall','a steamship','Sense 1 is the stairs meaning.','meaning'),Q(2,'Steps toward reopening the clinic are…','actions taken to achieve a goal','stairs leading to a roof','a person’s legal status','Sense 2 is the procedural meaning.','context'),Q(1,'Which phrase is natural?','climb the steps to the entrance','climb steps to the entrancely','a steps to climb entrance','The plural noun refers to the staircase.','grammar'),Q(1,'Steps is the plural of…','step','steep','stew','It takes the regular plural ending -s.','word-formation')]);
P('stereo','Stereo is short for stereophonic, from Greek stereos, “solid,” and phone, “sound”; it can name a two-speaker sound system, two-channel sound, or a sense of depth.',[C('stereo.s1','音响','They connected the turntable to a stereo with speakers on both sides of the room.','他们把唱机接到一套立体声音响上，房间两侧都放了扬声器。','a stereo system; turn on the stereo','名词，指通过两个扬声器播放录制声音的设备。','two speakers reproduce sound.','音响'),C('stereo.s2','音频','The album was recorded in stereo so that instruments sound separated across two channels.','这张专辑以立体声录制，因此不同乐器听起来分布在两个声道中。','stereo sound/recording; in stereo','形容词，指通过两个声道播放、听起来更自然的声音。','audio uses left and right channels.','音频'),C('stereo.s3','感知','The stereo effect made the footsteps seem to move from one side of the room to the other.','立体声效果让脚步声听起来像是从房间一侧移到另一侧。','a stereo effect/image','形容词，也指产生空间深度或环绕感的效果。','listener perceives direction and depth.','感知')],M('The recording was in stereo, using one channel and one speaker only.','The recording was in stereo, using two channels for a more spatial sound.','立体声区别于单声道，使用两个声道。','distinction'),[Q(1,'A stereo system is…','a machine that plays sound through two speakers','a machine that cooks with steam','a carved stone pillar','Sense 1 names the equipment.','meaning'),Q(2,'A stereo recording uses…','two sound channels','one channel only','no speakers or sound','Sense 2 is the audio format.','context'),Q(3,'A stereo effect can make sound seem…','spatial, with direction or depth','completely silent','like a legal rule','Sense 3 concerns perceived depth.','meaning'),Q(1,'Stereo is shortened from stereophonic, built from Greek stereos and…','phone, “sound”','stēlē, “pillar”','statuere, “set up”','The word combines ideas of solid/spatial and sound.','word-formation')]);
P('stereophotograph','Stereophotograph combines stereo + photograph; it is one of a pair of pictures taken from slightly different angles to create a three-dimensional view.',C('stereophotograph.s1','摄影','The curator placed a stereophotograph in a viewer so visitors could see depth in the old street scene.','策展人把一张立体照片放进观片器，让游客看出旧街景的纵深。','view a stereophotograph; pair of stereophotographs','名词，指从略有差异的角度拍摄、可呈现三维效果的一对照片之一。','viewer combines two perspectives.','摄影'),M('The curator called a single flat passport portrait a stereophotograph even though it had no paired viewpoint.','The curator used one of a paired set of photographs taken from slightly different angles.','立体照片依靠一对不同视角的图像呈现纵深。','meaning'),[Q(1,'A stereophotograph is…','one of two images that can create a three-dimensional view','a single flat image with no paired view','a medical listening instrument','That is the source definition.','meaning'),Q(1,'Why use a viewer for the old street image?','To combine the slightly different views and see depth','To remove every visual detail','To play stereo sound','The viewer enables the stereoscopic effect.','context'),Q(1,'Which phrase is natural?','view a stereophotograph through a viewer','view a stereophotographingly through','stereophotograph to view of','Through introduces the viewing device.','grammar'),Q(1,'Stereophotograph combines stereo and…','photograph','stethoscope','stepper','The compound names a photographic image with stereo depth.','word-formation')]);
P('stereoscopic','Stereoscopic combines stereo + -scopic, related to Greek skopein, “look”; it describes seeing depth by combining two images or producing that effect.',C('stereoscopic.s1','摄影','The viewer produced a stereoscopic image by presenting a slightly different picture to each eye.','观片器向左右眼分别呈现略有差异的图像，从而产生立体效果。','stereoscopic image/viewer/vision','形容词，指通过组合双眼所见的不同图像来呈现深度的。','each eye receives a distinct view.','摄影'),M('The stereoscopic viewer showed exactly the same flat image to both eyes and created no depth.','The stereoscopic viewer showed slightly different views to each eye to create depth.','立体视觉依赖两眼接收略有差异的图像。','meaning'),[Q(1,'Stereoscopic viewing creates…','a sense of depth by combining two images','a single flat image with no depth','a loud sound from two speakers','That is the optical sense.','meaning'),Q(1,'How did the viewer create a 3-D effect?','It showed a different image to each eye.','It showed no image to either eye.','It made the picture into a statute.','Different perspectives produce depth perception.','context'),Q(1,'Which phrase is natural?','a stereoscopic image','a stereoscopically image','stereoscopicize an image','Stereoscopic is an adjective modifying image.','grammar'),Q(1,'The ending -scopic relates to Greek skopein, “to…”','look','stand','cook','The word concerns visual perception.','word-formation')]);
P('stereotype','Stereotype comes from French stéréotype, originally a printing plate; its name combines Greek stereos, “solid,” and typos, “impression.” It means a fixed often inaccurate group idea or forming such an idea.',[C('stereotype.s1','社会','The article challenged the stereotype that older people cannot learn new technology.','这篇文章挑战了“老年人学不会新技术”这一刻板印象。','a stereotype about/of a group; challenge a stereotype','名词，指对某群体固定而常常错误的看法。','article questions overgeneralization.','社会'),C('stereotype.s2','社会','Do not stereotype a neighborhood by assuming every resident has the same background.','不要因为以为每位居民背景相同，就把整个社区模式化。','stereotype a group/person; be stereotyped as','及物动词，指对某人或群体形成固定而不公平的看法。','warning rejects blanket assumption.','社会')],M('The article rejected a stereotype by assuming every older person has exactly the same habits.','The article rejected the stereotype by showing that older people have varied abilities and interests.','用统一假设概括整个群体恰恰是在强化刻板印象。','meaning'),[Q(1,'A stereotype about a group is…','a fixed and often inaccurate general idea','a precise fact about every individual','a photograph in 3-D','That is the noun sense.','meaning'),Q(2,'To stereotype a neighborhood is to…','make an oversimplified fixed assumption about its residents','describe each resident individually and accurately','build a church steeple','Sense 2 is the verb.','context'),Q(1,'Which phrase is natural?','challenge a stereotype about age','challenge stereotype age aboutly','stereotype to challenge about age','About introduces the subject of the stereotype.','grammar'),Q(1,'Stereotype originally named a printing plate, from Greek stereos and…','typos, “impression”','stella, “star”','steik, “roast meat”','The historical term joined “solid” and “impression.”','word-formation')]);
P('stereotyped','Stereotyped is formed from stereotype + -ed; it describes something repeated in a fixed conventional form that ignores real variation.',C('stereotyped.s1','媒体','The film used a stereotyped villain whose motives never went beyond greed.','影片塑造了一个刻板化的反派，动机始终只有贪婪。','a stereotyped image/role; stereotyped view','形容词，指按固定老套模式呈现、忽视真实差异的。','character lacks individual variation.','媒体'),M('The film’s stereotyped character had a complex personal history and changed in unexpected ways.','The film’s stereotyped character followed a fixed, oversimplified pattern.','复杂且不断变化的个性不符合刻板、老套的呈现。','meaning'),[Q(1,'A stereotyped character is…','presented in a fixed conventional way','fully individualized with complex variation','a metal alloy','That is the adjective’s sense.','meaning'),Q(1,'What made the villain stereotyped?','His motives never went beyond a familiar simple pattern.','He changed in many unexpected ways.','He was a real historical witness.','The context points to a fixed characterization.','context'),Q(1,'Which phrase is natural?','a stereotyped role in the film','a stereotypically role','a stereotype rolely','Stereotyped is the adjective modifying role.','grammar'),Q(1,'Stereotyped is the past participle of…','stereotype','stereo','stare','The adjective comes from the verb stereotype.','word-formation')]);
P('stereotypical','Stereotypical is formed from stereotype + -ical; it means matching a fixed, oversimplified idea about a person or thing.',C('stereotypical.s1','社会','The stereotype of the quiet scientist is not true of every researcher, despite being familiar.','安静科学家的刻板形象虽然常见，却不适用于每一位研究者。','a stereotypical image/role; stereotypical of','形容词，指符合固定且过度简化的成见。','familiar image overgeneralizes.','社会'),M('The stereotypical portrait showed every individual’s unique history without relying on any fixed group idea.','The stereotypical portrait relied on a familiar, oversimplified group image.','不依赖固定群体观念的个性化肖像不是stereotypical。','meaning'),[Q(1,'A stereotypical image is…','based on a fixed oversimplified idea','a detailed account of every individual','a literal pair of photographs','That is the adjective’s meaning.','meaning'),Q(1,'Why is the quiet-scientist image stereotypical?','It generalizes one familiar trait to a whole group.','It accurately describes every researcher.','It is a statute.','The context highlights the overgeneralization.','context'),Q(1,'Which phrase is natural?','a stereotypical role in a film','a stereotypically role in a film','a role stereotypicality in film','Stereotypical is the adjective before role.','grammar'),Q(1,'Stereotypical is formed from stereotype plus…','-ical','-er','-less','The suffix forms the adjective meaning characteristic of a stereotype.','word-formation')]);
P('sterile','Sterile comes from Latin sterilis, “barren”; it means free of microorganisms, unable to reproduce or grow crops, or lacking fresh ideas.',[C('sterile.s1','医疗','The surgical tools were kept sterile until the operation began.','手术器械一直保持无菌，直到手术开始。','sterile equipment/field; keep something sterile','形容词，指没有细菌等微生物的。','tools are free of microbes.','医疗'),C('sterile.s2','生物','The sterile soil produced no crops, even after the farmers added water.','即使农民浇了水，这片贫瘠的土壤也长不出庄稼。','sterile soil/land; sterile animal','形容词，也指不能繁殖或无法生长作物的。','soil fails to produce crops.','生物'),C('sterile.s2','思想','The meeting became sterile when participants repeated old arguments and proposed nothing new.','与会者反复旧论点、毫无新提议，会议便变得毫无成果。','a sterile debate/discussion','形容词还可指缺乏新观点、没有成果的讨论。','no fresh ideas emerge.','思想')],M('The surgical tools were sterile, but they were covered in live bacteria.','The surgical tools were sterile and free of microorganisms.','无菌器械不能同时被活细菌覆盖。','meaning'),[Q(1,'Sterile surgical tools are…','free of bacteria and other microorganisms','covered in germs','unable to produce an argument','Sense 1 is the medical meaning.','meaning'),Q(2,'Sterile soil is…','unable to produce crops','rich and highly productive','a medical instrument','Sense 2 is biological.','context'),Q(2,'A sterile debate is one that…','produces no fresh ideas','introduces many useful proposals','is free of bacteria literally','Sense 2 can describe unproductive discussion.','meaning'),Q(1,'Which phrase is natural?','keep the instruments sterile','keep the instruments sterility','sterilely instruments keep','Sterile is an adjective after keep + object.','grammar')]);
P('sterilize','Sterilize comes from sterile + -ize; it means kill microorganisms on equipment or make a person, animal, or land unable to reproduce or produce crops.',[C('sterilize.s1','医疗','The clinic sterilized the reusable instruments before the next procedure.','诊所为下一台手术前的可重复使用器械进行了消毒灭菌。','sterilize equipment/bottles; sterilize by heat','及物动词，指杀灭器械或物质上的微生物。','heat kills microbes.','医疗'),C('sterilize.s2','生物','The program sterilizes stray cats to prevent unwanted litters.','该项目给流浪猫做绝育，以防止意外繁殖。','sterilize an animal/person; sterilize soil','动词，也指使人或动物不能繁殖，或使土地不能产出作物。','procedure prevents reproduction.','生物')],M('The clinic sterilized the instruments by covering them with bacteria before surgery.','The clinic sterilized the instruments by killing microorganisms before surgery.','sterilize医疗器械是杀灭微生物，不是增加细菌。','meaning'),[Q(1,'To sterilize instruments is to…','kill microorganisms on them','cover them with bacteria','make them easier to steer','Sense 1 is disinfection.','meaning'),Q(2,'A program sterilizes stray cats to…','prevent them from reproducing','make their fur sterile white','teach them stenography','Sense 2 is the reproductive meaning.','context'),Q(1,'Which phrase is correct?','sterilize the equipment before use','sterilize to the equipment before use','sterilized equipment before use it','The verb takes the equipment as a direct object.','grammar'),Q(1,'Sterilize is formed from sterile plus…','-ize','-ness','-er','The suffix creates a verb meaning make sterile.','word-formation')]);
P('sterling','Sterling has a historical connection with English silver coinage; it means very high quality or honesty, and it names the UK monetary standard or currency.',[C('sterling.s1','评价','The repair team did sterling work restoring the damaged clock.','维修团队修复受损时钟的工作十分出色。','sterling work/quality; a person of sterling character','形容词，表示品质极高、可靠或诚实正直。','restoration is excellent.','评价'),C('sterling.s2','金融','The invoice lists the fee in pounds sterling rather than euros.','发票上的费用以英镑而不是欧元标价。','pounds sterling; sterling exchange rate','名词或后置修饰语，指英国货币体系或英镑。','amount is stated in UK currency.','金融')],M('The team did sterling work, producing a careless repair that failed immediately.','The team did sterling work, restoring the clock to excellent condition.','sterling作评价时表示出色高质，不是粗心失败。','meaning'),[Q(1,'Sterling work is…','of very high quality','careless and ineffective','a type of medical tool','Sense 1 is praise.','meaning'),Q(2,'Pounds sterling refers to…','the United Kingdom’s currency standard','a type of steel','a public statute','Sense 2 is financial.','context'),Q(1,'Which phrase is natural?','pounds sterling','sterlingly pounds','a sterling of pounds','The established currency phrase is pounds sterling.','grammar'),Q(1,'Sterling is historically connected with…','English silver coinage','Greek steppe grasslands','Old English steam','The word became associated with English currency.','word-formation')]);
P('stern','Stern comes from Old English styrne, “severe”; the adjective means serious and strict or difficult, while a separate nautical noun names the back of a vessel.',[C('stern.s1','态度','The stern supervisor required everyone to wear safety glasses in the workshop.','这位严厉的主管要求所有人在车间里戴护目镜。','a stern expression/voice; stern with someone','形容词，指严肃、严格并显出不赞同。','rule is enforced firmly.','态度'),C('stern.s2','处境','The rescue crew faced a stern test when the storm cut off the mountain road.','暴风雪封闭山路后，救援队面临严峻考验。','a stern test/challenge; stern warning','形容词，也指困难而严峻的。','storm creates serious challenge.','处境'),C('stern.s3','航海','The small flag was tied to the stern of the boat.','小旗系在船尾。','at/from the stern; stern of a ship','名词，指船或艇的后端。','flag is at the rear.','航海')],M('The stern supervisor encouraged unsafe behavior and never enforced any rules.','The stern supervisor strictly enforced the workshop’s safety rules.','stern表示严厉严格，与纵容违反规则相反。','meaning'),[Q(1,'A stern supervisor is…','serious and strict','playful and unconcerned','a ship’s rear end','Sense 1 concerns manner.','meaning'),Q(2,'A stern test is…','a difficult and serious challenge','an easy exercise','a very high-quality review','Sense 2 means severe or demanding.','context'),Q(3,'The stern of a boat is…','its back end','its mast','its kitchen','Sense 3 is nautical.','meaning'),Q(1,'Which phrase is natural?','a stern warning','a sternly warning','stern warningly','Stern is an adjective modifying warning.','grammar')]);
P('stethoscope','Stethoscope combines Greek stēthos, “chest,” with skopein, “look, examine”; it is a medical instrument for listening to internal body sounds.',C('stethoscope.s1','医疗','The doctor used a stethoscope to listen to the patient’s heartbeat and breathing.','医生用听诊器听患者的心跳和呼吸。','use a stethoscope; stethoscope to the chest','名词，指有耳件和胸件、用于听取体内声音的医疗器械。','instrument carries internal sounds.','医疗'),M('The doctor used a stethoscope to inspect the patient’s height without listening to any body sounds.','The doctor used a stethoscope to listen to the heartbeat and breathing.','听诊器用于听体内声音，不是测量身高。','meaning'),[Q(1,'A stethoscope is used to…','listen to internal body sounds','measure a patient’s height','sterilize an operating room','That is the medical function.','meaning'),Q(1,'What did the doctor listen to?','The heartbeat and breathing','The patient’s legal status','The steamer engine','The context shows the instrument’s use.','context'),Q(1,'Which phrase is natural?','listen with a stethoscope','listen by stethoscope the','stethoscope listeningly with','With introduces the instrument used.','grammar'),Q(1,'Greek stēthos means…','chest','star','step','The instrument’s name begins with the Greek word for chest.','word-formation')]);
P('stew','Stew comes through Old French estuver, “heat in a vessel”; it is meat and vegetables slowly cooked in liquid or the method of cooking them.',[C('stew.s1','饮食','The beef stew simmered for three hours until the carrots and meat were tender.','牛肉炖菜慢炖了三个小时，直到胡萝卜和肉都变软。','beef/vegetable stew; a pot of stew','名词，指在有盖容器中用液体慢慢煮熟的肉菜。','slow cooking in liquid.','饮食'),C('stew.s2','烹饪','Stew the tomatoes over low heat until they soften and release their juices.','用小火炖西红柿，直到它们变软并释放汁液。','stew meat/fruit; stew slowly','及物动词，指在有盖容器中用低温液体慢慢烹煮。','low heat cooks food in liquid.','烹饪')],M('The cook made stew by leaving the meat raw and dry outside the pot.','The cook made stew by slowly cooking the meat and vegetables in liquid.','炖菜需在液体中慢煮，不是干放生肉。','meaning'),[Q(1,'Beef stew is…','meat and vegetables slowly cooked in liquid','a dry raw steak','a kind of ship','Sense 1 is the dish.','meaning'),Q(2,'To stew tomatoes is to…','cook them slowly in liquid over low heat','freeze them solid','paint them with a stencil','Sense 2 is the cooking verb.','context'),Q(1,'Which phrase is natural?','a pot of vegetable stew','a stewful vegetables pot','stew of pot vegetablesly','Of introduces the ingredients or type.','grammar'),Q(1,'Stew came through Old French related to heating food…','in a vessel','on a stage','by steamship only','The historical word referred to heating in a vessel.','word-formation')]);
P('steward','Steward comes from Old English stigweard, “house guardian”; it means a person serving passengers on a plane or ship, or someone managing property or an event.',[C('steward.s1','交通','The steward brought blankets to passengers during the overnight flight.','夜间航班上，乘务员给乘客送来了毯子。','flight/ship steward; ask a steward for help','名词，指在飞机或船上为乘客服务的人员。','employee serves travelers.','交通'),C('steward.s2','管理','A steward checked the festival grounds and coordinated the volunteer teams.','一名组织干事检查了节庆场地，并协调志愿者团队。','a club/event steward; steward of an estate','名词，也指管理财产或协助组织活动的人。','person oversees event operations.','管理')],M('The steward served passengers during the flight, although his only task was to pilot the aircraft.','The steward served passengers during the flight while the pilot flew the aircraft.','乘务员为乘客服务，驾驶飞机的是飞行员。','distinction'),[Q(1,'A flight steward…','serves passengers','writes statutes','repairs a steeple','Sense 1 is the transport role.','meaning'),Q(2,'A festival steward may…','coordinate volunteers and oversee the event','cook only a steak','control the plane','Sense 2 concerns management.','context'),Q(1,'Which phrase is natural?','ask a steward for a blanket','ask a stewarding for blanketly','ask to steward blanket','For introduces what the passenger requests.','grammar'),Q(1,'The Old English source of steward meant…','house guardian','metal worker','small statue','The compound originally referred to a household guardian.','word-formation')]);
P('stewardess','Stewardess is formed from steward + -ess and formerly named a woman who served passengers on a plane or managed a household; modern usage often prefers flight attendant.',C('stewardess.s1','航空','The stewardess checked that every passenger had fastened a seat belt before takeoff.','起飞前，空中乘务员检查了每位乘客是否系好安全带。','airline stewardess; stewardess on a flight','名词，旧式或传统称谓，指女性空乘人员。','crew member checks passenger safety.','航空'),M('The stewardess checked passenger seat belts, although she was a passenger who had no crew duties.','The stewardess checked passenger seat belts as a member of the cabin crew.','stewardess指乘务员，不是普通乘客。','meaning'),[Q(1,'A stewardess traditionally is…','a female flight attendant','a ship’s engine','a passenger who has no crew duties','That is the source sense.','meaning'),Q(1,'What did the stewardess check?','Whether passengers had fastened seat belts','Whether the steeple was tall','Whether the stew was hot','The example shows her cabin-crew duty.','context'),Q(1,'Which phrase is natural?','a stewardess on the flight','a stewardessly on flight','a stewardess of fly at','On introduces the flight where she works.','grammar'),Q(1,'Stewardess is formed from steward and…','-ess','-ity','-proof','The suffix traditionally marks a female person.','word-formation')]);
P('stewpot','Stewpot combines stew + pot; it is a pot used to simmer meat and vegetables slowly in liquid.',C('stewpot.s1','厨房','She placed the stewpot over low heat and added broth, potatoes, and onions.','她把炖锅放在小火上，加入肉汤、土豆和洋葱。','a heavy stewpot; cook in a stewpot','名词，指用来慢炖食物的锅。','pot contains food and broth over low heat.','厨房'),M('She used a stewpot to keep the ingredients dry and uncooked throughout the meal.','She used a stewpot to simmer the ingredients slowly in broth.','炖锅用于以液体慢煮食物。','meaning'),[Q(1,'A stewpot is…','a pot for slowly simmering food','a tool for carving a stele','a ship powered by steam','That is the kitchen sense.','meaning'),Q(1,'What went into the stewpot?','Broth, potatoes, and onions','A stethoscope and a statute','Only dry ice','The example shows ingredients cooked together.','context'),Q(1,'Which phrase is natural?','cook the meal in a stewpot','cook stewpotly the meal','stewpot meal into cooking at','In introduces the cooking vessel.','grammar'),Q(1,'Stewpot combines stew with…','pot','spout','step','The compound names the vessel used to make stew.','word-formation')]);
P('stick','Stick comes from Old English stician, “pierce, adhere”; it is a thin piece of wood, means attach with adhesive, or push in/become fixed/continue.',[C('stick.s1','物品','He found a straight stick on the path and used it to draw in the sand.','他在小路上捡到一根直树枝，用它在沙地上画画。','a walking/stick; a stick of wood','名词，指细长的木棍或树枝。','branch is used as a tool.','物品'),C('stick.s2','粘贴','Stick the label to the front of the box before sending it.','寄出前把标签贴到盒子正面。','stick something to/on; stick with glue','及物动词，指用黏性物质把东西固定在表面上。','label adheres to box.','粘贴'),C('stick.s3','坚持','If you stick to the plan, the repairs should finish by Friday.','如果你坚持按计划进行，维修应该能在周五前完成。','stick to a plan; stick with someone','动词短语，也指坚持做法，或刺入、卡住、继续。','continuing with plan helps completion.','坚持')],M('He stuck the label to the box by ensuring it fell off as soon as he touched it.','He stuck the label to the box by pressing its adhesive backing onto the surface.','stick表示粘牢，贴上后立刻脱落不符合。','meaning'),[Q(1,'A stick found on a path is…','a thin piece of wood','an adhesive label','a type of law','Sense 1 is the noun.','meaning'),Q(2,'Stick the label to the box means…','attach it with its adhesive','throw it away','draw with it in sand','Sense 2 is the verb for attaching.','context'),Q(3,'Stick to the plan means…','continue following it','abandon it immediately','put a wooden branch on it','Sense 3 is the figurative phrase.','meaning'),Q(1,'Which phrase is natural?','stick the label to the box','stick the box with the label toly','stick at box the label to','To introduces the surface receiving the label.','grammar')]);
P('stick shift','Stick shift combines stick and shift; it is the gear lever moved by hand in a vehicle, or a car equipped with a manual gearbox.',C('stick shift.s1','驾驶','She learned to drive a stick shift by practising the clutch and gear changes on quiet roads.','她在安静的道路上练习离合器和换挡，学会了驾驶手动挡汽车。','drive a stick shift; manual stick shift','名词，指手动变速杆，也可指配有手动变速箱的汽车。','driver changes gears by hand.','驾驶'),M('He drove a stick shift by letting the automatic transmission select every gear without touching a lever.','He drove a stick shift by changing gears with the manual lever.','stick shift表示手动换挡，不是自动变速。','distinction'),[Q(1,'A stick shift is…','a hand-operated gear lever or manual-transmission car','an automatic gearbox only','a wooden branch used to steer a boat','That is the driving sense.','meaning'),Q(1,'What did she practise?','Using the clutch and changing gears by hand','Changing a steeple’s clock','Steaming vegetables','The example describes manual driving.','context'),Q(1,'Which phrase is natural?','learn to drive a stick shift','learn drive stick shiftly','stick shift learn at drive','Learn to drive is the standard structure.','grammar'),Q(1,'Stick shift refers to shifting gears with…','a lever moved by hand','a spoon','a springboard','The stick is the manual gear lever.','meaning')]);
P('sticker','Sticker is formed from stick + -er; it is a small paper or plastic piece with adhesive on the back for attaching to a surface.',C('sticker.s1','物品','The child put a star sticker on the cover of her notebook.','孩子把一张星星贴纸贴在了笔记本封面上。','a label/decal sticker; peel off a sticker','名词，指背面带胶、可贴在表面上的小纸片或塑料片。','adhesive decoration goes on cover.','物品'),M('She put a sticker on the notebook, but it had no adhesive and immediately fell away.','She put an adhesive-backed sticker on the notebook cover.','贴纸背面有黏胶，才能贴在表面上。','meaning'),[Q(1,'A sticker is…','a small adhesive-backed piece of paper or plastic','a hand-operated gear lever','a hard metal alloy','That is the object’s source sense.','meaning'),Q(1,'What did the child decorate?','Her notebook cover','A church steeple','A steamship boiler','The sticker is placed on the cover.','context'),Q(1,'Which phrase is natural?','peel off the sticker','peel the stickerly offly','sticker peel at off','Peel off is a common phrasal verb for removing a sticker.','grammar'),Q(1,'Sticker is based on the verb…','stick','steer','stew','The noun names an item that sticks to a surface.','word-formation')]);
P('stickpin','Stickpin combines stick + pin; it is an ornamental pin passed through a necktie to hold it in place.',C('stickpin.s1','服饰','He fastened his tie with a silver stickpin before the formal dinner.','正式晚宴前，他用一枚银领带针别住了领带。','a tie stickpin; wear a stickpin','名词，指穿过领带、用于固定领带的装饰性别针。','pin holds tie in position.','服饰'),M('He used a stickpin to fasten the tie by placing it on the table without piercing the fabric.','He used a stickpin to secure the tie by passing the pin through it.','stickpin需穿过领带来固定。','meaning'),[Q(1,'A stickpin is…','an ornamental pin used to hold a necktie','a pin used to steer a ship','a label with glue','That is the clothing sense.','meaning'),Q(1,'Why did he fasten the tie with it?','To keep the tie in place at dinner','To decorate a steamboat engine','To cook a steak','The example states the pin’s function.','context'),Q(1,'Which phrase is natural?','a silver stickpin through the tie','a stickpinly silver through tie','silver the tie at stickpin','Through describes how the pin secures the tie.','grammar'),Q(1,'Stickpin combines stick and…','pin','stalk','spoon','The compound names the slender pin used to fasten clothing.','word-formation')]);
P('sticky','Sticky is formed from stick + -y; it means covered with something adhesive or difficult to handle or solve.',[C('sticky.s1','触感','The spilled syrup left the kitchen floor sticky.','洒出的糖浆让厨房地板变得黏糊糊的。','sticky fingers/surface; sticky with syrup','形容词，指表面覆有黏性物质、容易粘东西。','syrup adheres to floor.','触感'),C('sticky.s2','问题','The committee faced a sticky problem over how to divide the limited funds.','委员会面临一个棘手问题：如何分配有限资金。','a sticky situation/problem; get into a sticky spot','形容词也指难以处理或解决的。','limited budget creates dilemma.','问题')],M('The floor was sticky with syrup but did not adhere to anything and felt completely dry.','The floor was sticky with syrup and felt tacky underfoot.','sticky的触感义是表面发黏、容易粘附。','meaning'),[Q(1,'A sticky floor after a syrup spill is…','covered with an adhesive substance','dry and completely non-adhesive','a set of stairs','Sense 1 concerns texture.','meaning'),Q(2,'A sticky funding problem is…','difficult to handle or solve','easy to resolve immediately','a piece of adhesive paper','Sense 2 is figurative.','context'),Q(1,'Which phrase is natural?','sticky with syrup','stickyly with syrup','stickiness with syruply','With introduces the substance causing the tackiness.','grammar'),Q(1,'Sticky is formed from stick plus…','-y','-er','-ment','The suffix forms an adjective.','word-formation')]);
P('stiff','Stiff comes from Old English stīf; it means firm and hard to bend, or formal, unfriendly, or severe in manner.',[C('stiff.s1','身体','His shoulders felt stiff after sleeping in an awkward position.','以别扭姿势睡了一觉后，他觉得肩膀僵硬。','a stiff neck/joint; stiff and sore','形容词，指难以弯曲或活动、僵硬的。','movement is restricted.','身体'),C('stiff.s2','态度','The guests exchanged stiff greetings but soon relaxed over dinner.','客人们起初拘谨地互相问候，但晚餐时很快放松下来。','a stiff manner/smile; stiff and formal','形容词，也指不自然、拘谨、不友好或过于严厉。','initial manner is not relaxed.','态度')],M('His shoulders were stiff after sleeping, moving freely and painlessly in every direction.','His shoulders were stiff after sleeping and difficult to move comfortably.','身体僵硬意味着活动不灵活。','meaning'),[Q(1,'Stiff shoulders are…','hard to move or bend comfortably','completely relaxed and flexible','a legal statute','Sense 1 is physical rigidity.','meaning'),Q(2,'Stiff greetings are…','formal and not relaxed','warm and casual','extremely smelly','Sense 2 concerns manner.','context'),Q(1,'Which phrase is natural?','a stiff neck after sleeping','a stiffly neck after sleeping','a neck stiffeningly','Stiff is an adjective before neck.','grammar'),Q(1,'Stiff comes from Old English…','stīf','stēam','stēpel','The adjective descends from Old English stīf.','word-formation')]);
P('stiffen','Stiffen is formed from stiff + -en; it means become firm and difficult to bend or make a muscle tight and less easy to move.',[C('stiffen.s1','材料','The glue will stiffen as it dries, so shape the paper before it sets.','胶水干燥时会变硬，因此要趁它凝固前把纸塑好。','stiffen as it dries; stiffen a material','不及物动词，指物体变得坚硬、不易弯曲。','drying makes glue firm.','材料'),C('stiffen.s2','身体','His back stiffened when he heard the sudden crash behind him.','听到身后突然一声巨响时，他的背部肌肉绷紧了。','stiffen with fear; stiffen one’s muscles','动词，指使肌肉绷紧、僵硬，或身体变得紧张。','surprise tightens muscles.','身体')],M('The glue stiffened as it dried, becoming softer and easier to bend.','The glue stiffened as it dried and became firm.','stiffen表示变硬，不是变软。','meaning'),[Q(1,'Glue that stiffens…','becomes firm and less flexible','turns into a liquid again','becomes a sound recording','Sense 1 is material hardening.','meaning'),Q(2,'His back stiffened at a crash means his muscles…','became tight in a sudden reaction','relaxed completely','were sterilized','Sense 2 is bodily tension.','context'),Q(1,'Which construction is natural?','stiffen with fear','stiffen fear withly','stiffly with fearness','With introduces the cause of the reaction.','grammar'),Q(1,'Stiffen is formed from stiff plus…','-en','-ity','-er','The suffix forms a verb meaning become or make stiff.','word-formation')]);
P('stifle','Stifle is an old English verb with an uncertain deeper origin; it means suppress a feeling, idea, or activity, or make it difficult to breathe.',[C('stifle.s1','表达','The chair allowed criticism so that debate would not stifle new ideas.','主席允许提出批评，以免辩论压制新想法。','stifle debate/creativity; stifle a laugh','及物动词，指阻止情绪、想法或活动发展。','open debate protects ideas.','表达'),C('stifle.s2','呼吸','Smoke filled the small room and began to stifle the people inside.','烟雾充满小房间，里面的人开始感到窒息。','stifle someone; stifle under heat/smoke','动词，也指使人难以呼吸或感到窒息。','smoke blocks comfortable breathing.','呼吸')],M('The chair stifled debate by welcoming every new idea and giving speakers unlimited time.','The chair stifled debate by cutting off criticism and refusing to hear new ideas.','压制讨论意味着阻止观点表达，不是鼓励发言。','meaning'),[Q(1,'Stifle new ideas means…','prevent them from developing or being expressed','encourage every idea to grow','make an image stereoscopic','Sense 1 concerns suppression.','meaning'),Q(2,'Smoke began to stifle people means it…','made breathing difficult','made the air fresher','helped them sleep','Sense 2 concerns breathing.','context'),Q(1,'Which phrase is natural?','stifle a laugh','stifle to a laugh','stiflingly laugh a','Stifle takes the feeling as a direct object.','grammar'),Q(1,'The deeper origin of stifle is…','uncertain','certainly Greek for “star”','certainly Latin for “law”','No precise derivation is asserted.','word-formation')]);
P('stigma','Stigma comes from Greek stigma, “mark, brand”; it means social disapproval attached to a person, condition, or behavior.',C('stigma.s1','社会','Public discussion helped reduce the stigma attached to seeking mental-health care.','公开讨论有助于减轻寻求心理健康服务所背负的污名。','social stigma; stigma attached to; reduce stigma','名词，指社会对某事或某人施加的负面评价和耻辱感。','discussion reduces disapproval.','社会'),M('The stigma around mental-health care disappeared because everyone continued to shame people who sought help.','The stigma around mental-health care declined as people stopped shaming those who sought help.','持续羞辱会强化污名，不会消除污名。','meaning'),[Q(1,'Stigma around seeking care is…','social disapproval attached to the choice','a medical instrument','a physical step','That is the social sense.','meaning'),Q(1,'What helped reduce the stigma?','Open discussion of mental-health care','More public shaming','A steamship crossing','The context links discussion with lower disapproval.','context'),Q(1,'Which phrase is natural?','the stigma attached to illness','the stigma attaching illness toly','stigma to attached illness of','Attached to introduces the subject carrying the stigma.','grammar'),Q(1,'Greek stigma meant…','mark or brand','a fixed staircase','a strong metal','The social metaphor developed from a mark of disgrace.','word-formation')]);
P('still','Still has Old English roots; it can mean continuing up to a time, nevertheless, or motionless and quiet.',[C('still.s1','时间','She still works at the clinic even though she moved to another town.','尽管搬到了另一座城镇，她仍在诊所工作。','still works/exists; still not finished','副词，表示某情况一直持续到现在或所说时间。','work continues after move.','时间'),C('still.s2','转折','The road was icy; still, the driver chose to continue slowly.','路面结冰了；尽管如此，司机还是选择慢慢继续前行。','still, + clause; even so, still','副词，表示尽管前面所说情况如此，后面的事仍然发生。','contrast leads to cautious continuation.','转折'),C('still.s3','状态','The lake was perfectly still before the first boat crossed it.','第一艘船驶过之前，湖面完全平静无波。','still water/air; keep still','形容词，指不动、安静、没有明显活动。','water has no movement.','状态')],M('She still works at the clinic, meaning she stopped working there years ago.','She still works at the clinic, meaning the work continues now.','still表示延续到现在，不是早已停止。','meaning'),[Q(1,'She still works at the clinic means…','she continues to work there now','she stopped years ago','the lake is motionless','Sense 1 marks continuation.','meaning'),Q(2,'“The road was icy; still, he continued” means…','despite that fact, he continued','the road was not icy','he resigned from work','Sense 2 expresses contrast or nevertheless.','context'),Q(3,'A still lake is…','motionless and quiet','fast-flowing and noisy','full of steam','Sense 3 is the adjective.','meaning'),Q(1,'Which phrase uses still as a contrast adverb?','It was late; still, they waited.','The water was still.','She still works there.','The first example means nevertheless.','grammar')]);
P('stillness','Stillness is formed from still + -ness; it means absence of movement, sound, or disturbance.',C('stillness.s1','环境','The stillness of the forest broke when a branch fell onto the path.','一根树枝落到小路上，打破了森林的寂静。','complete/deep stillness; break the stillness','名词，不可数，指没有动作、声音或干扰的状态。','falling branch interrupts quiet.','环境'),M('The stillness of the forest was filled with loud traffic, shouting, and constant movement.','The stillness of the forest was marked by quiet and no movement.','嘈杂活动与静止、安静相反。','meaning'),[Q(1,'Stillness is…','absence of movement, sound, or disturbance','a fast-running race','a medical condition','That is the noun’s definition.','meaning'),Q(1,'What broke the forest’s stillness?','A branch fell onto the path.','A storm had already filled the woods with noise.','A law was passed.','The example shows a quiet state interrupted by sound.','context'),Q(1,'Which phrase is natural?','the stillness of the morning','the stillness morningly of','a stillnessful morning','Of links the quality to its setting.','grammar'),Q(1,'Stillness is formed from still plus…','-ness','-er','-ize','The suffix forms a noun for a state.','word-formation')]);
P('stilt','Stilt has an uncertain deeper origin; it is one of a pair of poles used to walk above the ground or a long post supporting a structure.',[C('stilt.s1','器具','The performer walked across the square on stilts several feet above the crowd.','表演者踩着高跷，在人群上方几英尺处穿过广场。','walk on stilts; a pair of stilts','名词，指成对使用、让人离地行走的长杆。','poles raise performer.','器具'),C('stilt.s1','建筑','The cabin stood on stilts above the flood-prone ground.','小屋架在支柱上，离开了容易被洪水淹没的地面。','a house on stilts; stilt-supported structure','名词，也指支撑建筑物的长柱。','posts raise building.','建筑')],M('The cabin stood on stilts by resting directly on the ground with no supporting posts.','The cabin stood on stilts, with long posts raising it above the ground.','stilt作为支柱时要支撑并抬高建筑。','meaning'),[Q(1,'A performer’s stilts are…','poles that let the person walk above the ground','small running shoes','a steeple','Sense 1 is the walking equipment.','meaning'),Q(1,'Why was the cabin raised on stilts?','Long posts supported it above flood-prone ground.','It was placed underground.','It was a steamship.','The context shows stilts as structural supports.','context'),Q(1,'Which phrase is natural?','walk on stilts','walk at stilts on','stilt walkingly on','On introduces the poles used for walking.','grammar'),Q(1,'The deeper origin of stilt is…','uncertain','certainly Greek for chest','certainly Old English for steam','The word’s earlier derivation is not established here.','word-formation')]);
P('stimulant','Stimulant comes from Latin stimulans, from stimulare, “goad, urge”; it is a drug, drink, or influence that makes the body or mind more active, or something stimulating.',[C('stimulant.s1','健康','The doctor advised him to avoid caffeine and other stimulants before bed.','医生建议他睡前避免咖啡因和其他兴奋剂。','a mild/powerful stimulant; stimulant drug','名词，指使身体或头脑活动增强的药物、饮料或影响。','caffeine increases alertness.','健康'),C('stimulant.s2','激励','The tax credit served as a stimulant for investment in energy-efficient homes.','这项税收抵免成为投资节能住宅的促进因素。','an economic stimulant; serve as a stimulant','名词也可指促进某过程或人更活跃的因素。','credit encourages investment.','经济')],M('Caffeine is a stimulant that reliably makes every person sleepy and less alert.','Caffeine is a stimulant that can increase alertness.','兴奋剂的典型作用是提高活跃度，而非让人昏昏欲睡。','meaning'),[Q(1,'Caffeine is called a stimulant because it can…','make the body or mind more active','stop all mental activity','sterilize equipment','Sense 1 is the substance meaning.','meaning'),Q(2,'A tax credit as a stimulant for investment…','encourages more investment','prevents any spending','is a medical instrument','Sense 2 is a figurative motivating influence.','context'),Q(1,'Which phrase is natural?','a stimulant drug','a stimulantize drug','a stimulatingly drug','Stimulant is a noun or adjective modifying drug.','grammar'),Q(1,'Stimulant comes from Latin stimulare, meaning…','goad or urge','stand or status','cook slowly','The source verb conveys prompting action.','word-formation')]);
P('stimulate','Stimulate comes from Latin stimulare, “goad, urge”; it means make a bodily process more active or encourage a person’s interest or action.',[C('stimulate.s1','健康','The medication stimulates the patient’s breathing when it becomes dangerously slow.','当患者呼吸慢到危险程度时，这种药物会刺激呼吸。','stimulate growth/activity; stimulate a nerve','及物动词，指使身体部位或某个过程活动增强。','medicine increases breathing activity.','健康'),C('stimulate.s2','教育','The teacher used a debate to stimulate students’ interest in local history.','老师用辩论激发学生对地方历史的兴趣。','stimulate interest/curiosity; stimulate someone to act','动词，也指激励某人产生兴趣或采取行动。','debate encourages curiosity.','教育')],M('The teacher stimulated interest in history by forbidding questions and discouraging students from reading.','The teacher stimulated interest by inviting questions and discussion.','禁止提问、阻止阅读会压制而非激发兴趣。','meaning'),[Q(1,'A medicine that stimulates breathing…','makes the process more active','stops breathing entirely','makes the patient’s tie sticky','Sense 1 is bodily activation.','meaning'),Q(2,'A debate can stimulate students’ interest by…','encouraging curiosity and questions','forbidding discussion','making the class sterile','Sense 2 is motivating interest.','context'),Q(1,'Which phrase is correct?','stimulate interest in history','stimulate to interest history in','stimulating interestfully history','In introduces the subject of interest.','grammar'),Q(1,'Stimulate comes from Latin stimulare, meaning…','goad or urge','make a statue','be motionless','The word’s origin suggests prompting activity.','word-formation')]);
P('stimulating','Stimulating is formed from stimulate + -ing; it describes something that creates interest, energy, or new ideas.',C('stimulating.s1','学习','The lecturer led a stimulating discussion that left students with new questions to explore.','讲师主持了一场启发思考的讨论，让学生产生了新的探索问题。','a stimulating conversation/class; find something stimulating','形容词，指能引起兴趣、活力或新想法的。','discussion provokes curiosity.','学习'),M('The stimulating discussion made everyone bored and left them with no questions or ideas.','The stimulating discussion sparked interest and gave students new ideas to consider.','stimulating表示引起兴趣或新想法，不是令人厌倦。','meaning'),[Q(1,'A stimulating discussion…','creates interest or new ideas','makes everyone bored','is a silent medical device','That is the adjective’s meaning.','meaning'),Q(1,'What did students gain from the lecture?','New questions to explore','A fixed stereotype','A stick shift','The context illustrates intellectual stimulation.','context'),Q(1,'Which phrase is natural?','a stimulating conversation','a stimulatingly conversation','a stimulation conversationly','Stimulating is an adjective before conversation.','grammar'),Q(1,'Stimulating is based on the verb…','stimulate','stiffen','stint','The -ing adjective describes what stimulates.','word-formation')]);
P('stimulation','Stimulation comes from Latin stimulatio, from stimulare, “goad”; it is the process of making the body, mind, or economy more active.',C('stimulation.s1','健康','The therapist used gentle stimulation to help restore movement in the patient’s hand.','治疗师用温和刺激帮助患者恢复手部活动。','sensory/nerve stimulation; provide stimulation','名词，不可数，指激发身体、头脑或经济活动的过程。','treatment prompts activity.','健康'),M('The stimulation restored movement by preventing the nerves and muscles from responding at all.','The stimulation helped the nerves and muscles become active again.','刺激促进反应或活动，不是阻止所有反应。','meaning'),[Q(1,'Stimulation is…','the process of rousing a body or system to activity','the act of making something still forever','a legal status','That is the noun’s sense.','meaning'),Q(1,'Why did the therapist use stimulation?','To help restore movement in the hand','To make the hand unable to respond','To keep the patient awake with a stimulant drink','The context describes physical activation.','context'),Q(1,'Which phrase is natural?','sensory stimulation','sensory stimulate','stimulationly sensory','Stimulation is the noun following the adjective sensory.','grammar'),Q(1,'Stimulation comes from Latin stimulatio, based on…','stimulare, “goad or urge”','stare, “stand”','stēlē, “pillar”','The word family conveys prompting activity.','word-formation')]);
P('stimulus','Stimulus comes from Latin stimulus, “goad, pointed stick”; it means an event causing a biological response, a factor encouraging development, or a motive for action.',[C('stimulus.s1','生理','A sudden flash of light acted as a stimulus that made the pupil contract.','突然的闪光成为刺激，使瞳孔收缩。','a visual/sensory stimulus; respond to a stimulus','名词，指使生物体、细胞或感官产生反应的变化或事件。','light triggers a bodily reaction.','生理'),C('stimulus.s2','经济','The grant provided a stimulus for small businesses to hire more workers.','这笔拨款促进了小企业雇用更多员工。','an economic stimulus; stimulus for growth','名词，也指推动活动、过程或经济加快发展的因素。','funding encourages hiring.','经济'),C('stimulus.s3','动机','The promise of a scholarship was the stimulus that persuaded her to apply.','奖学金的承诺成为促使她申请的动力。','a stimulus to action; provide the stimulus','名词，也指促使某人行动或作决定的动机。','reward prompts application.','动机')],M('The flash acted as a stimulus but caused no reaction in the pupil or any other sense.','The flash acted as a stimulus and made the pupil contract.','生理刺激引发反应，不能同时毫无反应。','meaning'),[Q(1,'A flash is a stimulus for the pupil when it…','causes the pupil to contract','is ignored without any response','provides a salary','Sense 1 is biological response.','meaning'),Q(2,'A grant as an economic stimulus…','encourages business activity','prevents hiring','is a motive for a person to travel only','Sense 2 concerns economic growth.','context'),Q(3,'A scholarship promise as a stimulus means it…','motivates someone to apply','causes a pupil to contract','makes a ship stable','Sense 3 is a motive for action.','meaning'),Q(1,'The plural of stimulus is…','stimuli','stimuluses only','stimula','Stimulus has the Latin plural stimuli.','plural')]);
P('sting','Sting comes from Old English stingan, “pierce”; it means wound with a sharp body part, cause a sharp or emotional hurt, or a sharp pain/pointed organ.',[C('sting.s1','昆虫','A wasp stung his hand when he moved the nest.','他移动蜂巢时，一只黄蜂蜇了他的手。','sting someone; bee/wasp sting','动词，指用身体尖刺刺伤或叮伤。','insect pierces skin.','昆虫'),C('sting.s2','感受','Her criticism stung because it was accurate and delivered in front of the team.','她的批评让人难受，因为它确实说中了问题，而且当着全队的面说出。','words/comments sting; sting someone','动词，也指言语或经历造成尖锐的情绪痛苦。','public criticism hurts emotionally.','感受'),C('sting.s3','昆虫','The bee’s sting remained in the skin after the insect flew away.','蜜蜂飞走后，刺针还留在皮肤里。','a bee/wasp sting; feel a sting','名词，指刺痛或昆虫用来蜇人的尖刺。','barbed part stays in skin.','昆虫')],M('The wasp stung him but did not touch his skin or use its pointed body part.','The wasp stung him by piercing his skin with its pointed part.','sting作动词表示用尖刺蜇刺。','meaning'),[Q(1,'A wasp stung his hand means it…','wounded his skin with a sharp part','comforted his hand','stiffened the skin','Sense 1 is the physical action.','meaning'),Q(2,'Criticism stung her means it…','caused emotional hurt','made her physically taller','helped her cook stew','Sense 2 is figurative pain.','context'),Q(3,'A bee’s sting may refer to…','its sharp organ or the sharp pain','its wing color only','the hive’s legal status','Sense 3 is the noun.','meaning'),Q(1,'Which phrase is natural?','a wasp stung his hand','a wasp stinged his hand','a wasp was sting his hand','Sting is an irregular verb: sting, stung, stung.','verb-form')]);
P('stinger','Stinger is formed from sting + -er; it names a stinging organ or creature, or a remark that causes a sharp emotional hurt.',[C('stinger.s1','动物','The beekeeper removed the bee’s stinger after the insect was safely brushed away.','蜜蜂被安全拂开后，养蜂人取出了它的刺针。','bee/wasp stinger; remove a stinger','名词，指昆虫用于蜇刺的器官，也可指有蜇刺的生物或伤人的话。','pointed organ is removed.','动物')],M('The bee’s stinger was a soft feather that could not pierce skin.','The bee’s stinger was a pointed organ capable of piercing skin.','stinger指能蜇刺的尖锐器官，不是柔软羽毛。','meaning'),[Q(1,'A bee’s stinger is…','the pointed organ it uses to sting','a soft feather','a speaker in a stereo','That is the biological sense.','meaning'),Q(1,'Why did the beekeeper remove it?','It was the bee’s stinging organ.','It was a stick shift.','It was a sterile tool.','The context identifies the stinger.','context'),Q(1,'Which phrase is natural?','remove the stinger carefully','remove the stingery carefully','the stinger remove carefulness','Stinger names the object being removed.','grammar'),Q(1,'Stinger is formed from sting plus…','-er','-ity','-less','The suffix names an agent or instrument.','word-formation')]);
P('stingy','Stingy is probably related to sting + -y, suggesting reluctance to part with money; it means unwilling to give or spend what is needed.',C('stingy.s1','金钱','The stingy owner refused to replace the broken safety lights in the hallway.','吝啬的房东拒绝更换走廊里坏掉的安全灯。','stingy with money/time; a stingy person','形容词，指不愿把钱给别人或花在所需事物上的。','owner withholds needed repair money.','金钱'),M('The owner was stingy with repairs, spending freely on every necessary improvement.','The owner was stingy with repairs and refused to spend money on needed lights.','stingy表示不愿付出或花费，与慷慨支出相反。','meaning'),[Q(1,'A stingy owner is…','unwilling to spend money on needed things','generous with every expense','a medical professional','That is the adjective’s sense.','meaning'),Q(1,'What showed the owner was stingy?','He refused to replace broken safety lights.','He paid for every repair immediately.','He installed a stethoscope.','The example shows reluctance to spend.','context'),Q(1,'Which phrase is natural?','stingy with money','stingy money withly','a stingy of money','With introduces the resource someone is unwilling to share or spend.','grammar'),Q(1,'Stingy is probably related to sting plus…','-y','-er','-tion','The adjective uses the suffix -y.','word-formation')]);
P('stink','Stink comes from Old English stincan, “emit an odor”; it means give off a strong unpleasant smell, the smell itself, or be very bad/unfair informally.',[C('stink.s1','气味','The drain stinks after food scraps have been left in it for a week.','食物残渣在下水道里留了一周后，那里散发出恶臭。','stink of/like; the room stinks','不及物动词，指散发出强烈难闻的气味。','waste produces odor.','气味'),C('stink.s2','气味','A stink from the blocked drain filled the hallway.','堵塞的下水道散出的臭味充满了走廊。','a terrible stink; stink of + source','名词，指充满某处的强烈难闻气味。','odor fills hallway.','气味'),C('stink.s3','评价','The unfair rule stinks, especially because it punishes people for reporting hazards.','这条不公平的规定糟透了，尤其因为它惩罚举报隐患的人。','that stinks; something stinks','非正式动词，表示某事很糟或不公平、令人恼火。','rule is objectionable.','评价')],M('The blocked drain stinks of fresh roses and produces no unpleasant odor.','The blocked drain stinks of rotting food and produces an unpleasant odor.','stink指难闻的强烈气味，不是鲜花香气。','meaning'),[Q(1,'The drain stinks means it…','gives off a strong unpleasant smell','is completely odorless','is a medical instrument','Sense 1 is the verb for odor.','meaning'),Q(2,'A stink from a drain is…','a strong unpleasant smell','a church tower','a step in a plan','Sense 2 is the noun.','context'),Q(3,'“That unfair rule stinks” means it…','is very bad or objectionable','smells of fresh flowers literally','is a good legal statute','Sense 3 is informal criticism.','meaning'),Q(1,'Which phrase is natural?','the room stinks of smoke','the room stinks smoke ofly','the room is stink of smoke','Of introduces the source of the smell.','grammar')]);
P('stinking','Stinking is formed from stink + -ing; it means giving off a very strong unpleasant smell, or informally emphasizes something extremely bad.',[C('stinking.s1','气味','Stinking fish was removed from the refrigerator before the smell spread.','气味扩散前，散发恶臭的鱼就被从冰箱里拿走了。','stinking garbage/fish; stinking of smoke','形容词，指散发出强烈难闻气味的。','odor prompts removal.','气味'),C('stinking.s2','评价','The team had a stinking day after two players were injured and the match was cancelled.','两名队员受伤、比赛又取消后，球队度过了糟透的一天。','a stinking mess/day; stinking rich (informal)','非正式形容词，用来加强语气，表示极糟或令人不快。','multiple setbacks make day awful.','评价')],M('The stinking fish gave off a fresh pleasant scent that everyone enjoyed.','The stinking fish gave off a powerful unpleasant odor.','stinking表示气味难闻浓烈。','meaning'),[Q(1,'Stinking fish is fish that…','gives off a very strong unpleasant smell','is completely fresh and odorless','has a stinger','Sense 1 is literal.','meaning'),Q(2,'A stinking day is…','an extremely bad or unpleasant day','a day with excellent results','a short period of lodging','Sense 2 is informal emphasis.','context'),Q(1,'Which phrase is natural?','stinking garbage','stinkingly garbage','stinkful garbage','Stinking is an adjective modifying garbage.','grammar'),Q(1,'Stinking is formed from the verb…','stink','sting','stint','It is the present participle used adjectivally.','word-formation')]);
P('stint','Stint is of uncertain deeper origin; as a noun it is a limited period doing a job, and as a verb it means provide something unwillingly or in too small an amount.',[C('stint.s1','工作','She completed a two-year stint as a nurse in a rural clinic.','她在乡村诊所做了两年护士。','a brief/long stint; a stint as + job','名词，指从事某项工作的一段有限时期。','two years is a defined work period.','工作'),C('stint.s2','供给','The school did not stint on safety equipment when it opened the chemistry lab.','学校开放化学实验室时，在安全设备方面没有吝惜投入。','stint on something; stint someone of something','动词，指吝惜或限量提供资源、帮助等。','school provides enough supplies.','供给')],M('The school did not stint on safety equipment, giving students none at all.','The school did not stint on safety equipment and supplied everything necessary.','not stint on表示不吝惜、不短缺，不是不给。','meaning'),[Q(1,'A two-year stint as a nurse is…','a limited period spent doing that job','a permanent building','a biological stimulus','Sense 1 is the noun meaning a period.','meaning'),Q(2,'The school did not stint on equipment means it…','provided enough rather than limiting supplies','refused to provide any','gave away the laboratory','Sense 2 is the verb meaning hold back.','context'),Q(1,'Which phrase is natural?','a stint as a nurse','a stint nurse asly','stint in nurse as','As introduces the role.','grammar'),Q(1,'The deeper origin of stint is…','uncertain','certainly Greek for stimulus','certainly from steamship','The word’s earlier derivation is not settled.','word-formation')]);
P('stipend','Stipend comes from Latin stipendium, “pay, tax,” from stips “contribution” + pendere “pay”; it is a fixed sum paid periodically, often for work not receiving a full commercial salary.',C('stipend.s1','教育','The research student received a monthly stipend to cover basic living costs.','这名研究生每月领取一笔津贴，用来支付基本生活费用。','receive/earn a stipend; monthly stipend','名词，指定期发放的固定款项，常用于支持研究或非商业性工作。','regular payment supports student.','教育'),M('The student received a stipend, an unpredictable one-time prize that was never paid again.','The student received a fixed monthly stipend to support ongoing research.','stipend通常是定期支付的固定款项。','meaning'),[Q(1,'A research stipend is…','a fixed sum paid periodically','a one-time unpredictable prize only','a type of musical stereo','That is the source sense.','meaning'),Q(1,'What did the monthly stipend cover?','Basic living costs','The cost of a steeple','A steamship engine only','The context shows the payment’s purpose.','context'),Q(1,'Which phrase is natural?','receive a monthly stipend','receive stipendly monthly','a stipend receive to monthly','Receive takes the payment as an object.','grammar'),Q(1,'Latin stipendium meant…','pay or tax','star or constellation','to stick something','The word’s history is connected with payment.','word-formation')]);
})();
